  1	//! After `version`/`snapshot`, each ecosystem's locked install must still succeed against a real subprocess.
  2	
  3	use std::fs;
  4	use std::path::{Path, PathBuf};
  5	use std::process::Command;
  6	
  7	use callisto_cli::cli::{AddArgs, GlobalArgs, OutputFormat, SnapshotArgs, VersionArgs};
  8	use callisto_cli::commands;
  9	
 10	/// Finds `program` on `PATH`, the way a shell would; never panics, so a tool-specific assertion can skip cleanly.
 11	fn find_on_path(program: &str) -> Option<PathBuf> {
 12	    std::env::var_os("PATH").and_then(|path| {
 13	        std::env::split_paths(&path)
 14	            .map(|dir| dir.join(program))
 15	            .find(|candidate| candidate.is_file())
 16	    })
 17	}
 18	
 19	/// A mixed Cargo + npm workspace with real lockfiles and cross-workspace dependency edges, committed to git.
 20	fn setup_mixed_native_resolution_workspace(root: &Path) {
 21	    callisto_fixtures::git::init_repo(root);
 22	
 23	    fs::write(
 24	        root.join("Cargo.toml"),
 25	        "[workspace]\nmembers = [\"crates/core\", \"crates/app\"]\nresolver = \"2\"\n",
 26	    )
 27	    .unwrap();
 28	    fs::create_dir_all(root.join("crates/core/src")).unwrap();
 29	    fs::write(
 30	        root.join("crates/core/Cargo.toml"),
 31	        "[package]\nname = \"core\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
 32	    )
 33	    .unwrap();
 34	    fs::write(root.join("crates/core/src/lib.rs"), "pub fn hello() {}\n").unwrap();
 35	
 36	    fs::create_dir_all(root.join("crates/app/src")).unwrap();
 37	    fs::write(
 38	        root.join("crates/app/Cargo.toml"),
 39	        "[package]\nname = \"app\"\nversion = \"1.0.0\"\nedition = \"2021\"\n\n\
 40	         [dependencies]\ncore = { path = \"../core\", version = \"1.0.0\" }\n",
 41	    )
 42	    .unwrap();
 43	    fs::write(root.join("crates/app/src/lib.rs"), "").unwrap();
 44	
 45	    fs::write(
 46	        root.join("package.json"),
 47	        r#"{"name":"root-ws","private":true,"version":"0.0.0","workspaces":["packages/*"]}"#,
 48	    )
 49	    .unwrap();
 50	    fs::create_dir_all(root.join("packages/lib")).unwrap();
 51	    fs::write(
 52	        root.join("packages/lib/package.json"),
 53	        r#"{"name":"@ws/lib","version":"1.0.0"}"#,
 54	    )
 55	    .unwrap();
 56	    fs::create_dir_all(root.join("packages/app")).unwrap();
 57	    fs::write(
 58	        root.join("packages/app/package.json"),
 59	        r#"{"name":"@ws/app","version":"1.0.0","dependencies":{"@ws/lib":"^1.0.0"}}"#,
 60	    )
 61	    .unwrap();
 62	
 63	    // Lockfiles are generated before any callisto command runs, so the later check is a real regression test.
 64	    assert!(Command::new("cargo")
 65	        .args(["generate-lockfile"])
 66	        .current_dir(root)
 67	        .status()
 68	        .unwrap()
 69	        .success());
 70	
 71	    if find_on_path("npm").is_some() {
 72	        assert!(Command::new("npm")
 73	            .args(["install", "--package-lock-only", "--ignore-scripts"])
 74	            .current_dir(root)
 75	            .status()
 76	            .unwrap()
 77	            .success());
 78	    }
 79	
 80	    assert!(Command::new("git")
 81	        .args(["add", "-A"])
 82	        .current_dir(root)
 83	        .status()
 84	        .unwrap()
 85	        .success());
 86	    assert!(Command::new("git")
 87	        .args(["-c", "commit.gpgSign=false", "commit", "-q", "-m", "Initial commit"])
 88	        .current_dir(root)
 89	        .status()
 90	        .unwrap()
 91	        .success());
 92	}
 93	
 94	/// `cargo metadata --locked --offline` always; `npm ci` too, when npm is on PATH.
 95	fn assert_native_resolution(root: &Path) {
 96	    let cargo_out = Command::new("cargo")
 97	        .args(["metadata", "--locked", "--offline", "--format-version", "1"])
 98	        .current_dir(root)
 99	        .output()
100	        .unwrap();
101	    assert!(
102	        cargo_out.status.success(),
103	        "cargo metadata --locked --offline must succeed; stderr: {}",
104	        String::from_utf8_lossy(&cargo_out.stderr)
105	    );
106	
107	    if find_on_path("npm").is_some() {
108	        let npm_out = Command::new("npm").args(["ci"]).current_dir(root).output().unwrap();
109	        assert!(
110	            npm_out.status.success(),
111	            "npm ci must succeed after the workspace's manifests are bumped; stderr: {}",
112	            String::from_utf8_lossy(&npm_out.stderr)
113	        );
114	    }
115	}
116	
117	#[test]
118	fn workspace_resolves_natively_after_version() {
119	    let dir = tempfile::tempdir().unwrap();
120	    let root = dir.path();
121	    setup_mixed_native_resolution_workspace(root);
122	
123	    let global = GlobalArgs {
124	        format: OutputFormat::Json,
125	        cwd: root.to_path_buf(),
126	        dry_run: false,
127	    };
128	
129	    commands::add::handle(
130	        AddArgs {
131	            packages: vec!["core:major".to_string(), "@ws/lib:major".to_string()],
132	            summary: Some("Bump core and lib".to_string()),
133	        },
134	        &global,
135	    )
136	    .unwrap();
137	
138	    commands::version::handle(
139	        VersionArgs {
140	            refresh_lockfiles: false,
141	            no_refresh_lockfiles: false,
142	            strict: false,
143	            allow_empty_changesets: false,
144	            emit_decision: None,
145	        },
146	        &global,
147	    )
148	    .unwrap();
149	
150	    assert_native_resolution(root);
151	}
