154	fn workspace_resolves_natively_after_snapshot() {
155	    let dir = tempfile::tempdir().unwrap();
156	    let root = dir.path();
157	    setup_mixed_native_resolution_workspace(root);
158	
159	    let global = GlobalArgs {
160	        format: OutputFormat::Json,
161	        cwd: root.to_path_buf(),
162	        dry_run: false,
163	    };
164	
165	    commands::snapshot::handle(
166	        SnapshotArgs {
167	            tag: "canary".to_string(),
168	            strict: false,
169	        },
170	        &global,
171	    )
172	    .unwrap();
173	
174	    assert_native_resolution(root);
175	}
