177	/// A pnpm workspace, plus a real uv one when `include_python`.
178	fn setup_pnpm_and_uv_workspace(root: &Path, include_python: bool) {
179	    callisto_fixtures::git::init_repo(root);
180	
181	    fs::write(
182	        root.join("package.json"),
183	        r#"{"name":"pnpm-root","private":true,"version":"0.0.0"}"#,
184	    )
185	    .unwrap();
186	    fs::write(root.join("pnpm-workspace.yaml"), "packages:\n  - \"packages/*\"\n").unwrap();
187	    fs::create_dir_all(root.join("packages/lib")).unwrap();
188	    fs::write(
189	        root.join("packages/lib/package.json"),
190	        r#"{"name":"@ws/lib","version":"1.0.0"}"#,
191	    )
192	    .unwrap();
193	    fs::create_dir_all(root.join("packages/app")).unwrap();
194	    fs::write(
195	        root.join("packages/app/package.json"),
196	        r#"{"name":"@ws/app","version":"1.0.0","dependencies":{"@ws/lib":"workspace:^1.0.0"}}"#,
197	    )
198	    .unwrap();
199	
200	    if include_python {
201	        fs::write(
202	            root.join("pyproject.toml"),
203	            "[tool.uv.workspace]\nmembers = [\"py/core\", \"py/app\"]\n",
204	        )
205	        .unwrap();
206	        fs::create_dir_all(root.join("py/core")).unwrap();
207	        fs::write(
208	            root.join("py/core/pyproject.toml"),
209	            "[project]\nname = \"core-py\"\nversion = \"1.0.0\"\nrequires-python = \">=3.9\"\ndependencies = []\n",
210	        )
211	        .unwrap();
212	        fs::create_dir_all(root.join("py/app")).unwrap();
213	        fs::write(
214	            root.join("py/app/pyproject.toml"),
215	            "[project]\nname = \"app-py\"\nversion = \"1.0.0\"\nrequires-python = \">=3.9\"\n\
216	             dependencies = [\"core-py>=1.0.0,<2.0.0\"]\n\n\
217	             [tool.uv.sources]\ncore-py = { workspace = true }\n",
218	        )
219	        .unwrap();
220	    }
221	
222	    if find_on_path("pnpm").is_some() {
223	        assert!(Command::new("pnpm")
224	            .args(["install", "--lockfile-only"])
225	            .current_dir(root)
226	            .status()
227	            .unwrap()
228	            .success());
229	    }
230	    if include_python && find_on_path("uv").is_some() {
231	        assert!(Command::new("uv")
232	            .args(["lock"])
233	            .current_dir(root)
234	            .status()
235	            .unwrap()
236	            .success());
237	    }
238	
239	    assert!(Command::new("git")
240	        .args(["add", "-A"])
241	        .current_dir(root)
242	        .status()
243	        .unwrap()
244	        .success());
245	    assert!(Command::new("git")
246	        .args(["-c", "commit.gpgSign=false", "commit", "-q", "-m", "Initial commit"])
247	        .current_dir(root)
248	        .status()
249	        .unwrap()
250	        .success());
251	}
