253	/// `pnpm install --frozen-lockfile` always; `uv lock --check` too when `include_python`; each tool-gated.
254	fn assert_pnpm_and_uv_resolution(root: &Path, include_python: bool) {
255	    if find_on_path("pnpm").is_some() {
256	        let pnpm_out = Command::new("pnpm")
257	            .args(["install", "--frozen-lockfile"])
258	            .current_dir(root)
259	            .output()
260	            .unwrap();
261	        assert!(
262	            pnpm_out.status.success(),
263	            "pnpm install --frozen-lockfile must succeed after the workspace's manifests are bumped; stderr: {}",
264	            String::from_utf8_lossy(&pnpm_out.stderr)
265	        );
266	    }
267	
268	    if include_python && find_on_path("uv").is_some() {
269	        let uv_out = Command::new("uv")
270	            .args(["lock", "--check"])
271	            .current_dir(root)
272	            .output()
273	            .unwrap();
274	        assert!(
275	            uv_out.status.success(),
276	            "uv lock --check must succeed after the workspace's manifests are bumped; stderr: {}",
277	            String::from_utf8_lossy(&uv_out.stderr)
278	        );
279	    }
280	}
