  1	#![cfg(target_os = "linux")]
  2	
  3	//! Real-registry e2e coverage. Linux only: CI installs the registries there.
  4	//!
  5	//! `release_forge_publish_e2e_tests.rs` and `durable_release_e2e_tests.rs`
  6	//! cover npm and PyPI publish only against fake providers. This file adds a
  7	//! real local Verdaccio registry to the mix: `callisto release execute`'s
  8	//! actual npm provider adapter, real `npm`, real HTTP over loopback. The
  9	//! fake-provider suites are unchanged and remain the fast, hermetic default.
 10	//!
 11	//! Registry routing goes entirely through npm's own `.npmrc` (a project-root
 12	//! file, gitignored so it never dirties the release-trust worktree check),
 13	//! never a callisto registry binding: `registry_endpoint::canonical_registry_url`
 14	//! rejects non-https URLs with no loopback exception, by design, so a local `http://127.0.0.1` test
 15	//! registry can never be configured as a `[registries]` entry. Leaving the
 16	//! package unmatched by any `[registries]` override keeps
 17	//! `PreparedRegistryBinding.endpoint` at `None`, which is also what makes
 18	//! this reachable at all: both `npm view` (observation) and `npm publish`
 19	//! omit `--registry` whenever `endpoint` is `None`, so npm resolves the
 20	//! registry itself from `.npmrc` -- unlike PyPI's observation step, which
 21	//! hardcodes the public simple index when `endpoint` is `None` (see the PyPI
 22	//! note below).
 23	//!
 24	//! PyPI drives `registry_argv::pypi_publish_argv` directly (the exact
 25	//! production build-then-upload argv, including `--repository-url` for a
 26	//! private index) rather than through `callisto release execute`: that CLI
 27	//! path routes a registry through `PreparedRegistryBinding`, whose
 28	//! `canonical_registry_url` rejects non-https with no loopback exception --
 29	//! by design -- so a callisto
 30	//! registry binding can never target a local `http://127.0.0.1` test index.
 31	//! Calling `pypi_publish_argv` directly stays on the same side of that line
 32	//! as the npm test above: real registry, real package-manager config
 33	//! (`--repository-url`, not `.pypirc`), zero callisto-side registry binding.
 34	//! `pypi_publish_argv` used to unconditionally append `--skip-existing`,
 35	//! which twine 5 and newer refuses to run at all against a non-warehouse
 36	//! repository URL (`UnsupportedConfiguration`) -- fixed to be conditional;
 37	//! see the `fix(publish)` commit on this branch and the `pypi_publish_argv_*`
 38	//! `--skip-existing` tests in `registry_argv.rs`.
 39	//!
 40	//! Cargo drives `registry_argv::cargo_publish_argv` directly against a real
 41	//! local `cargo-http-registry`, for a third, different reason than PyPI's:
 42	//! `cargo publish --registry <key>` and `cargo info --registry <key>` never
 43	//! carry a URL at all, only the registry's *name* -- the URL lives entirely
 44	//! in `.cargo/config.toml`, which callisto never writes. So the one
 45	//! `PreparedRegistryBinding` requirement that would block this (an `https`
 46	//! callisto-side binding) never applies: a `[registries]` entry with a
 47	//! `kind` and no `url` leaves `endpoint` at `None` and the key still reaches
 48	//! `cargo` as `--registry local-e2e`. Driving `cargo_publish_argv` directly
 49	//! here (rather than through `callisto release execute`) keeps this test
 50	//! independent of the git-remote scheme check (`https`/`ssh` only), which is
 51	//! an orthogonal gate on the *release commit's* origin, not on the registry.
 52	//! `cargo-http-registry` serves a git-protocol index (not sparse), so
 53	//! `.cargo/config.toml` also needs `net.git-fetch-with-cli = true` --
 54	//! libgit2's HTTP client rejects the server's dumb-protocol content type.
 55	
 56	#[path = "common/release_harness.rs"]
 57	mod release_harness;
 58	
 59	use std::fs;
 60	use std::net::TcpStream;
 61	use std::path::{Path, PathBuf};
 62	use std::process::{Child, Command, Stdio};
 63	use std::time::{Duration, Instant};
 64	
 65	use callisto_graph::commands::registry_argv::{cargo_publish_argv, pypi_publish_argv, Argv};
 66	use callisto_model::{Version, VersionGrammar};
 67	use release_harness::*;
 68	
 69	/// Finds `program` on `PATH`, the way a shell would. Never panics, so a test
 70	/// can skip cleanly when the real tool isn't installed.
 71	fn find_on_path(program: &str) -> Option<PathBuf> {
 72	    std::env::var_os("PATH").and_then(|path| {
 73	        std::env::split_paths(&path)
 74	            .map(|dir| dir.join(program))
 75	            .find(|candidate| candidate.is_file())
 76	    })
 77	}
 78	
 79	/// An ephemeral loopback port: bind to port 0, read back what the OS
 80	/// assigned, release it immediately. The gap between release and the real
 81	/// server binding it is a bounded TOCTOU risk, acceptable for test
 82	/// infrastructure that owns the box.
 83	fn free_loopback_port() -> u16 {
 84	    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("loopback listener must bind");
 85	    listener
 86	        .local_addr()
 87	        .expect("listener must have a local address")
 88	        .port()
 89	}
 90	
 91	/// A spawned server process, killed on drop so a panicking assertion never
 92	/// leaks it past the test. `log_path` is its combined stdout+stderr, written
 93	/// to a file rather than piped so a chatty server can never fill an
 94	/// undrained pipe and deadlock the test.
 95	struct ServerGuard {
 96	    child: Child,
 97	    log_path: PathBuf,
 98	}
 99	
100	impl ServerGuard {
101	    fn log(&self) -> String {
102	        fs::read_to_string(&self.log_path).unwrap_or_default()
103	    }
104	}
105	
106	impl Drop for ServerGuard {
107	    fn drop(&mut self) {
108	        drop(self.child.kill());
109	        drop(self.child.wait());
110	    }
111	}
112	
113	/// Redirects a spawned command's stdout and stderr to one combined log file
114	/// under `dir`/`name`, so a startup crash is diagnosable instead of silent.
115	fn log_to_file(command: &mut Command, dir: &Path, name: &str) -> PathBuf {
116	    let log_path = dir.join(name);
117	    let file = fs::File::create(&log_path).expect("server log file must be creatable");
118	    let file_for_stderr = file.try_clone().expect("log file handle must be cloneable");
119	    command.stdin(Stdio::null()).stdout(file).stderr(file_for_stderr);
120	    log_path
121	}
122	
123	/// Blocks until `port` accepts a loopback TCP connection, or panics after
124	/// `timeout` -- including the server's captured output in the panic message
125	/// either way, and its exit status if it already died. Checking `try_wait`
126	/// first means a server that crashes at startup fails fast with its real
127	/// error instead of spinning out the whole timeout with no evidence.
128	fn wait_for_port(guard: &mut ServerGuard, port: u16, timeout: Duration) {
129	    let deadline = Instant::now() + timeout;
130	    loop {
131	        if TcpStream::connect(("127.0.0.1", port)).is_ok() {
132	            return;
133	        }
134	        if let Ok(Some(status)) = guard.child.try_wait() {
135	            panic!(
136	                "server exited with {status} before binding 127.0.0.1:{port}; output:\n{}",
137	                guard.log()
138	            );
139	        }
140	        if Instant::now() >= deadline {
141	            panic!(
142	                "server on 127.0.0.1:{port} never became reachable within {timeout:?}; output:\n{}",
143	                guard.log()
144	            );
145	        }
146	        std::thread::sleep(Duration::from_millis(100));
147	    }
148	}
