150	/// GETs `url` with `curl` -- the same tool callisto's own PyPI observation
151	/// uses -- for an assertion independent of callisto's own HTTP client code.
152	fn curl_get(url: &str) -> String {
153	    let output = Command::new("curl")
154	        .args(["-sS", url])
155	        .output()
156	        .expect("curl must be runnable");
157	    assert!(
158	        output.status.success(),
159	        "curl {url} failed: {}",
160	        String::from_utf8_lossy(&output.stderr)
161	    );
162	    String::from_utf8_lossy(&output.stdout).into_owned()
163	}
