166	/// anonymous publish enabled (`access`/`publish`/`unpublish: $all`) and no
167	/// uplinks configured, so a lookup for an unknown package fails closed (404)
168	/// instead of reaching the real npm registry. Panics if it never becomes
169	/// reachable; callers check `find_on_path("verdaccio")` first.
170	fn start_verdaccio(external: &Path) -> (ServerGuard, u16) {
171	    let config_dir = external.join("verdaccio");
172	    fs::create_dir_all(config_dir.join("storage")).unwrap();
173	    fs::write(
174	        config_dir.join("config.yaml"),
175	        "storage: ./storage\n\
176	         self_path: ./storage\n\
177	         web:\n  enable: false\n\
178	         log: { type: stdout, format: pretty, level: warn }\n\
179	         packages:\n  '**':\n    access: $all\n    publish: $all\n    unpublish: $all\n",
180	    )
181	    .unwrap();
182	    let port = free_loopback_port();
183	    let mut command = Command::new("verdaccio");
184	    command.args(["-c", "config.yaml", "-l", &format!("127.0.0.1:{port}")]);
185	    command.current_dir(&config_dir);
186	    let log_path = log_to_file(&mut command, external, "verdaccio.log");
187	    let child = command.spawn().expect("verdaccio must be spawnable");
188	    let mut guard = ServerGuard { child, log_path };
189	    wait_for_port(&mut guard, port, Duration::from_secs(20));
190	    (guard, port)
