268	/// A real Verdaccio registry, npm routed to it purely via
269	/// `.npmrc`, `callisto release execute`'s real npm provider adapter, and an
270	/// assertion against the registry's own package metadata afterward -- not
271	/// just callisto's exit code.
272	#[test]
273	fn npm_publish_against_a_real_verdaccio_registry_is_retrievable_afterward() {
274	    let Some(_verdaccio) = find_on_path("verdaccio") else {
275	        eprintln!("SKIPPED npm real-registry e2e: `verdaccio` is not installed");
276	        return;
277	    };
278	
279	    let (dir, release_commit) = npm_registry_release_fixture(NPM_PACKAGE);
280	    let root = dir.path();
281	    let external = tempfile::tempdir().unwrap();
282	
283	    let intent = external.path().join("release-intent.json");
284	    let plan = callisto(
285	        root,
286	        &[
287	            "release",
288	            "plan",
289	            "--from-release-commit",
290	            &release_commit,
291	            "--decision",
292	            DECISION_PATH,
293	            "--out",
294	            intent.to_str().unwrap(),
295	        ],
296	    );
297	    assert!(plan.status.success(), "release plan failed: {}", stderr_of(&plan));
298	
299	    let (_verdaccio_guard, port) = start_verdaccio(external.path());
300	
301	    // npm's own configuration, not a callisto registry binding: no
302	    // `[registries]` entry exists, so `PreparedRegistryBinding.endpoint`
303	    // stays `None` and neither `npm view` nor `npm publish` ever receives a
304	    // `--registry` flag from callisto -- both fall through to this file.
305	    fs::write(
306	        root.join(".npmrc"),
307	        format!("registry=http://127.0.0.1:{port}/\n//127.0.0.1:{port}/:_authToken=callisto-e2e-test-token\n"),
308	    )
309	    .unwrap();
310	    assert_eq!(
311	        git(root, &["status", "--porcelain"]),
312	        "",
313	        ".npmrc must be gitignored, not dirty the sealed release commit"
314	    );
315	
316	    let bare = bare_remote(external.path());
317	    let mut rig = Rig::new(external.path(), &release_commit);
318	    rig.real_git_push(&bare, NPM_ORIGIN);
319	
320	    let receipt = external.path().join("release-receipt.json");
321	    let tag = format!("{NPM_PACKAGE}@0.2.0");
322	    let output = execute_rig(root, &intent, &receipt, &rig, &tag, &[], None);
323	    assert!(
324	        output.status.success(),
325	        "real-registry npm release execute failed: {}\neffect log:\n{}",
326	        stderr_of(&output),
327	        fs::read_to_string(&rig.log).unwrap_or_default(),
328	    );
329	    assert!(receipt.exists(), "a successful release must persist a terminal receipt");
330	
331	    // Independent verification against the registry itself: the published
332	    // version must be visible in Verdaccio's own package metadata, not just
333	    // inferred from callisto's exit code.
334	    let metadata_raw = curl_get(&format!("http://127.0.0.1:{port}/{NPM_PACKAGE}"));
335	    let metadata: serde_json::Value = serde_json::from_str(&metadata_raw)
336	        .unwrap_or_else(|error| panic!("registry metadata was not JSON: {error}\n{metadata_raw}"));
337	    assert!(
338	        metadata["versions"]["0.2.0"].is_object(),
339	        "published version must be retrievable from the registry's own package metadata: {metadata}"
340	    );
341	
342	    assert!(
343	        git(&bare, &["tag", "--list", &tag]).contains(&tag),
344	        "the release tag must reach the remote"
345	    );
346	}
