376	/// Starts a real local `pypiserver` on an ephemeral loopback port with
377	/// authentication fully disabled (`-a . -P .`, its own documented way to
378	/// allow anonymous browsing and uploads) and `--disable-fallback`, so a
379	/// lookup for an unknown project 404s instead of proxying to real PyPI.
380	///
381	/// `--server gunicorn`: pypiserver's default `auto` backend selection falls
382	/// through to `wsgiref` when nothing else is installed, and `wsgiref`
383	/// (like `paste` and gevent's `pywsgi`, also measured) resolves the bind
384	/// address via `socket.getfqdn()` before it starts listening -- a reverse
385	/// DNS lookup that measured 12-35s on a real machine exhibiting the same
386	/// symptom as the CI macOS runner, against sub-second on Linux. `gunicorn`
387	/// has no such call anywhere in its source (grepped) and measured
388	/// consistently under 1s across repeated runs here; it forks a worker and
389	/// terminates both master and worker cleanly on the one SIGTERM `ServerGuard`
390	/// sends the master PID.
391	fn start_pypiserver(external: &Path) -> (ServerGuard, u16) {
392	    let packages_dir = external.join("pypiserver-packages");
393	    fs::create_dir_all(&packages_dir).unwrap();
394	    let port = free_loopback_port();
395	    let mut command = Command::new("pypi-server");
396	    command.args([
397	        "run",
398	        "--server",
399	        "gunicorn",
400	        "--host",
401	        "127.0.0.1",
402	        "--port",
403	        &port.to_string(),
404	        "--authenticate",
405	        ".",
406	        "--passwords",
407	        ".",
408	        "--disable-fallback",
409	        packages_dir.to_str().unwrap(),
410	    ]);
411	    let log_path = log_to_file(&mut command, external, "pypiserver.log");
412	    let child = command.spawn().expect("pypi-server must be spawnable");
413	    let mut guard = ServerGuard { child, log_path };
414	    wait_for_port(&mut guard, port, Duration::from_secs(20));
415	    (guard, port)
416	}
