113	/// Redirects a spawned command's stdout and stderr to one combined log file
114	/// under `dir`/`name`, so a startup crash is diagnosable instead of silent.
115	fn log_to_file(command: &mut Command, dir: &Path, name: &str) -> PathBuf {
116	    let log_path = dir.join(name);
117	    let file = fs::File::create(&log_path).expect("server log file must be creatable");
118	    let file_for_stderr = file.try_clone().expect("log file handle must be cloneable");
