123	/// Blocks until `port` accepts a loopback TCP connection, or panics after
124	/// `timeout` -- including the server's captured output in the panic message
125	/// either way, and its exit status if it already died. Checking `try_wait`
126	/// first means a server that crashes at startup fails fast with its real
127	/// error instead of spinning out the whole timeout with no evidence.
128	fn wait_for_port(guard: &mut ServerGuard, port: u16, timeout: Duration) {
129	    let deadline = Instant::now() + timeout;
130	    loop {
131	        if TcpStream::connect(("127.0.0.1", port)).is_ok() {
132	            return;
133	        }
134	        if let Ok(Some(status)) = guard.child.try_wait() {
135	            panic!(
136	                "server exited with {status} before binding 127.0.0.1:{port}; output:\n{}",
137	                guard.log()
138	            );
139	        }
140	        if Instant::now() >= deadline {
141	            panic!(
142	                "server on 127.0.0.1:{port} never became reachable within {timeout:?}; output:\n{}",
143	                guard.log()
144	            );
145	        }
146	        std::thread::sleep(Duration::from_millis(100));
147	    }
148	}
