438	/// Runs an `Argv` exactly as the production `run_argv` does (see
439	/// `provider/registry.rs`), just without a `CommandRunner` in the way.
440	fn run_argv(argv: &Argv, extra_env: &[(&str, &str)]) -> std::process::Output {
441	    let mut command = Command::new(&argv.program);
442	    command.args(&argv.args).current_dir(&argv.cwd).stdin(Stdio::null());
443	    for (key, value) in extra_env {
444	        command.env(key, value);
445	    }
446	    command.output().unwrap_or_else(|error| {
447	        panic!(
448	            "{} {:?} (cwd {}) must be runnable: {error}",
449	            argv.program,
450	            argv.args,
451	            argv.cwd.display()
452	        )
453	    })
454	}
