456	/// A real pypiserver registry, `registry_argv::pypi_publish_argv`'s
457	/// exact production build-then-upload argv (including `--repository-url`,
458	/// callisto's own package-manager-config routing, not a registry binding),
459	/// and an assertion against the registry's own simple index afterward -- not
460	/// just the upload's exit code.
461	#[test]
462	fn pypi_publish_against_a_real_pypiserver_registry_is_retrievable_afterward() {
463	    if find_on_path("pypi-server").is_none() {
464	        eprintln!("SKIPPED pypi real-registry e2e: `pypi-server` is not installed");
465	        return;
466	    }
467	    let Some(interpreter) = resolved_python() else {
468	        eprintln!("SKIPPED pypi real-registry e2e: neither `python3` nor `python` is on PATH");
469	        return;
470	    };
471	    if !python_module_importable(interpreter, "build") || find_on_path("twine").is_none() {
472	        eprintln!("SKIPPED pypi real-registry e2e: the `build` module or `twine` is not installed");
473	        return;
474	    }
475	
476	    let dir = tempfile::tempdir().unwrap();
477	    let root = dir.path();
478	    pypi_package_fixture(root, PYPI_PACKAGE, PYPI_VERSION);
479	
480	    let external = tempfile::tempdir().unwrap();
481	    let (_pypiserver_guard, port) = start_pypiserver(external.path());
482	    let index = format!("http://127.0.0.1:{port}");
483	
484	    let version = Version::parse(PYPI_VERSION, VersionGrammar::SemVer).unwrap();
485	    let steps = pypi_publish_argv(root, Path::new(""), PYPI_PACKAGE, &version, Some(index.as_str())).unwrap();
486	    let [build, upload] = steps.as_slice() else {
487	        panic!("pypi_publish_argv must return exactly a build and an upload step");
488	    };
489	    assert!(
490	        upload.args.contains(&"--repository-url".to_string()) && upload.args.contains(&index),
491	        "twine must be routed via --repository-url, not a callisto registry binding: {:?}",
492	        upload.args
493	    );
494	
495	    // `--no-isolation`: production `pypi_publish_argv` deliberately omits it (a real release
496	    // wants a clean, isolated build), but a plain `python -m build` here would pip-install
497	    // `setuptools` from PyPI into a fresh isolated env -- network access CI must not depend on.
498	    // The CI venv (see callisto-ci.yml) pre-installs pinned `setuptools`/`wheel`, so building
499	    // against it directly, unisolated, needs nothing from the network; `PIP_NO_INDEX=1` makes
500	    // that a hard failure instead of a silent fetch if isolation is ever attempted anyway.
501	    let offline_build = Argv {
502	        program: build.program.clone(),
503	        args: build
504	            .args
505	            .iter()
506	            .cloned()
507	            .chain(["--no-isolation".to_string()])
508	            .collect(),
509	        cwd: build.cwd.clone(),
510	    };
511	    let built = run_argv(&offline_build, &[("PIP_NO_INDEX", "1")]);
512	    assert!(
513	        built.status.success(),
514	        "python -m build failed: {}",
515	        String::from_utf8_lossy(&built.stderr)
516	    );
517	
518	    // pypiserver's `-a . -P .` disables authentication entirely, but twine's
519	    // own client still refuses to run with no credentials configured at
520	    // all -- the package manager's own config, same as npm's dummy
521	    // `_authToken` above, not a callisto concern.
522	    let uploaded = run_argv(
523	        upload,
524	        &[("TWINE_USERNAME", "callisto-e2e"), ("TWINE_PASSWORD", "callisto-e2e")],
525	    );
526	    assert!(
527	        uploaded.status.success(),
528	        "twine upload failed: {}",
529	        String::from_utf8_lossy(&uploaded.stderr)
530	    );
531	
532	    // Independent verification against the registry itself: the published
533	    // version must be visible in pypiserver's own PEP 691 JSON simple index,
534	    // not just inferred from twine's exit code.
535	    let simple_index = curl_get(&format!("http://127.0.0.1:{port}/simple/{PYPI_PACKAGE}/"));
536	    assert!(
