 74	            .current_dir(root)
 75	            .status()
 76	            .unwrap()
 77	            .success());
 78	    }
 79	
 80	    assert!(Command::new("git")
 81	        .args(["add", "-A"])
 82	        .current_dir(root)
 83	        .status()
 84	        .unwrap()
 85	        .success());
