  86	/// `init` against explicit terminal state, prompter, output streams, and command runner.
  87	pub fn run<R: CommandRunner>(
  88	    args: InitArgs,
  89	    global: &GlobalArgs,
  90	    interactive: bool,
  91	    prompter: &mut dyn Prompter,
  92	    out: &mut dyn Write,
  93	    err: &mut dyn Write,
  94	    runner: &R,
  95	) -> Result<ExitCode, CliError> {
  96	    validate_flags(&args)?;
  97	    let root = workspace_root(global, runner)?;
  98	    let locator = IgnoreWalkLocator::new(&root);
  99	    let facts = scaffold::detect(&root, &locator, runner)?;
 100	    let json = global.format == OutputFormat::Json;
 101	    // JSON keeps stdout for the report.
 102	    let human: &mut dyn Write = if json { &mut *err } else { &mut *out };
 103	    write_facts(&facts, human)?;
 104	
 105	    if facts.origin.is_none() {
 106	        if args.workflow {
 107	            return Err(CliError::InitFlagRequiresOrigin { flag: "workflow" });
 108	        }
 109	        if !args.artifact_targets.is_empty() {
 110	            return Err(CliError::InitFlagRequiresOrigin {
 111	                flag: "artifact-target",
 112	            });
 113	        }
 114	    }
 115	    if !interactive && !args.yes {
 116	        let mut missing = vec!["--yes"];
 117	        missing.extend(missing_flags(&args, &facts));
 118	        return Err(CliError::InitRequiresYes { missing });
 119	    }
 120	    if args.yes {
 121	        let missing = missing_flags(&args, &facts);
 122	        if !missing.is_empty() {
 123	            return Err(CliError::InitMissingFlags { missing });
 124	        }
 125	    }
 126	    let prompting = interactive && !args.yes;
 127	    let answers = collect_answers(&args, &facts, prompting, prompter)?;
 128	
 129	    let mut diagnostics = scaffold::changesets_config_diagnostics(&facts.root);
 130	    if facts.origin.is_none() {
 131	        writeln!(human, "{ORIGIN_MISSING_NOTE}")?;
 132	        diagnostics.push(callisto_model::Diagnostic {
 133	            code: callisto_model::DiagnosticCode::InitOriginMissing,
 134	            severity: callisto_model::DiagnosticSeverity::Warning,
 135	            message: ORIGIN_MISSING_NOTE.to_owned(),
 136	            package: None,
 137	            path: None,
 138	            escalated_by: None,
 139	            governed_by: None,
 140	        });
 141	    }
 142	    let shape = match scaffold::workflow_shape(&facts, &answers) {
 143	        Err(reason) if args.workflow => {
 144	            return Err(GraphError::InitWorkflowUnsupported {
 145	                reason: reason.to_string(),
 146	            }
 147	            .into());
 148	        }
 149	        Err(reason) => {
 150	            let note = workflow_unsupported_note(reason);
 151	            writeln!(human, "{note}")?;
 152	            diagnostics.push(callisto_model::Diagnostic {
 153	                code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
 154	                severity: callisto_model::DiagnosticSeverity::Warning,
 155	                message: note,
 156	                package: None,
 157	                path: None,
 158	                escalated_by: None,
 159	                governed_by: None,
 160	            });
 161	            None
 162	        }
 163	        Ok(shape) => Some(shape),
 164	    };
 165	    let want_workflow = match shape {
 166	        None => false,
 167	        Some(_) if args.workflow => true,
 168	        Some(_) if args.no_workflow => false,
 169	        Some(_) if prompting && facts.origin.is_some() => prompter.confirm(WORKFLOW_PROMPT, false)?,
 170	        Some(_) => false,
 171	    };
 172	    let workflow = match shape.filter(|_| want_workflow) {
 173	        Some(shape) => {
 174	            scaffold::ensure_workflow_absent(&facts.root)?;
 175	            let branch = scaffold::default_branch(runner, &facts.root);
 176	            writeln!(human, "  default branch: {} (from {})", branch.name, branch.source)?;
 177	            let version = env!("CARGO_PKG_VERSION");
 178	            let commit = scaffold::resolve_release_commit(runner, &facts.root, version)?;
 179	            let content = scaffold::render_workflow(&facts, shape, &branch.name, &commit, version);
 180	            Some((content, branch.name))
 181	        }
 182	        None => None,
 183	    };
 184	
 185	    let config = scaffold::render_config(&facts, &answers);
 186	    let plan = if facts.has_commit {
 187	        Some(scaffold::preview(&facts, &config, &locator, runner)?)
 188	    } else {
 189	        None
 190	    };
 191	    writeln!(human, "\ncallisto.toml:\n{config}")?;
 192	    match plan {
 193	        Some(plan) => {
 194	            writeln!(human, "First release preview (`callisto release --dry-run`):")?;
 195	            super::release::write_release_preview(plan.as_ref(), OutputFormat::Text, human)?;
 196	        }
 197	        None => writeln!(human, "{NO_COMMITS}")?,
 198	    }
 199	    if let Some((workflow, _)) = &workflow {
 200	        writeln!(
 201	            human,
 202	            "\n{}:\n{workflow}",
 203	            scaffold::workflow_path(&facts.root).display()
 204	        )?;
 205	    }
 206	
 207	    // Computed before any write, so the `.changeset/README.md` existence check sees disk state as-is.
 208	    let files = scaffold::init_files(&facts.root, workflow.is_some());
 209	    let mut report = if global.dry_run {
 210	        InitReport {
 211	            schema_version: SCHEMA_VERSION,
 212	            initialized: false,
 213	            config_path: facts.root.join("callisto.toml"),
 214	            config,
 215	            files,
 216	            diagnostics: Vec::new(),
 217	        }
 218	    } else {
 219	        if prompting && !prompter.confirm(WRITE_PROMPT, true)? {
 220	            writeln!(human, "Initialization cancelled; nothing was written.")?;
 221	            return Ok(ExitCode::SUCCESS);
 222	        }
 223	        let permit = ApplyPermit::granted_unless_dry_run(false).expect("non-dry-run permits writes");
 224	        let mut report = scaffold::write(&facts.root, &config, &permit)?;
 225	        if let Some((workflow, branch)) = &workflow {
 226	            scaffold::write_workflow(&facts.root, workflow, &permit)?;
 227	            let note = merge_publishes_note(branch);
 228	            writeln!(human, "{note}")?;
 229	            diagnostics.push(callisto_model::Diagnostic {
 230	                code: callisto_model::DiagnosticCode::WorkflowMergePublishes,
 231	                severity: callisto_model::DiagnosticSeverity::Info,
 232	                message: note,
 233	                package: None,
 234	                path: None,
 235	                escalated_by: None,
 236	                governed_by: None,
 237	            });
 238	        }
 239	        report.files = files;
 240	        report
 241	    };
 242	    report.diagnostics.extend(diagnostics);
 243	    if json {
 244	        emit_report(&mut &mut *out, &report, global.dry_run)?;
 245	    } else {
 246	        render::render_init(&report, &mut &mut *out)?;
 247	    }
 248	    Ok(ExitCode::SUCCESS)
 249	}
