 411	
 412	    #[derive(Clone, Default)]
 413	    struct Shared(Rc<RefCell<Vec<u8>>>);
 414	
 415	    impl Shared {
 416	        fn text(&self) -> String {
 417	            String::from_utf8(self.0.borrow().clone()).unwrap()
 418	        }
 419	    }
 420	
 421	    impl Write for Shared {
 422	        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
 423	            self.0.borrow_mut().extend_from_slice(buf);
 424	            Ok(buf.len())
 425	        }
