 431	    enum Answer {
 432	        Select(usize),
 433	        Confirm(bool),
 434	        Input(&'static str),
 435	    }
 436	
 437	    /// Answers in order; records each prompt with how much output preceded it.
 438	    struct Scripted {
 439	        answers: VecDeque<Answer>,
 440	        asked: Vec<(String, Option<String>)>,
 441	        output: Shared,
 442	        output_at_first_prompt: Option<String>,
 443	    }
 444	
 445	    impl Scripted {
 446	        fn new(answers: Vec<Answer>, output: &Shared) -> Self {
 447	            Scripted {
 448	                answers: answers.into(),
 449	                asked: Vec::new(),
 450	                output: output.clone(),
 451	                output_at_first_prompt: None,
 452	            }
 453	        }
 454	
 455	        fn next(&mut self, prompt: &str, default: Option<&str>) -> Answer {
 456	            self.output_at_first_prompt.get_or_insert_with(|| self.output.text());
 457	            self.asked.push((prompt.to_owned(), default.map(str::to_owned)));
 458	            self.answers
 459	                .pop_front()
 460	                .unwrap_or_else(|| panic!("unexpected prompt `{prompt}`"))
 461	        }
 462	
 463	        fn prompts(&self) -> Vec<&str> {
 464	            self.asked.iter().map(|(prompt, _)| prompt.as_str()).collect()
 465	        }
 466	    }
