 498	    /// A Cargo workspace: `bins` binary crates (`app`, `tool`) plus library `core`, with `origin`.
 499	    fn workspace(bins: usize) -> tempfile::TempDir {
 500	        workspace_with_origin(bins, true)
 501	    }
 502	
 503	    /// Same workspace shape as [`workspace`], with no `origin` remote configured.
 504	    fn workspace_without_origin(bins: usize) -> tempfile::TempDir {
 505	        workspace_with_origin(bins, false)
