 508	    fn workspace_with_origin(bins: usize, origin: bool) -> tempfile::TempDir {
 509	        let dir = tempfile::tempdir().unwrap();
 510	        let root = dir.path();
 511	        let mut members = vec!["core"];
 512	        members.extend(["app", "tool"].into_iter().take(bins));
 513	        let list: Vec<String> = members.iter().map(|member| format!("\"{member}\"")).collect();
 514	        std::fs::write(
