 549	    struct Run {
 550	        result: Result<ExitCode, CliError>,
 551	        out: String,
 552	        prompter: Scripted,
 553	    }
 554	
 555	    fn run_init(root: &Path, args: InitArgs, interactive: bool, answers: Vec<Answer>, dry_run: bool) -> Run {
 556	        run_init_with_runner(root, args, interactive, answers, dry_run, &CliCommandRunner)
 557	    }
 558	
 559	    fn run_init_with_runner<R: CommandRunner>(
 560	        root: &Path,
 561	        args: InitArgs,
 562	        interactive: bool,
 563	        answers: Vec<Answer>,
 564	        dry_run: bool,
 565	        runner: &R,
 566	    ) -> Run {
 567	        let out = Shared::default();
 568	        let err = Shared::default();
 569	        let mut prompter = Scripted::new(answers, &out);
 570	        let result = run(
 571	            args,
 572	            &global(root, OutputFormat::Text, dry_run),
 573	            interactive,
 574	            &mut prompter,
 575	            &mut out.clone(),
 576	            &mut err.clone(),
 577	            runner,
 578	        );
 579	        Run {
 580	            result,
 581	            out: out.text(),
 582	            prompter,
 583	        }
 584	    }
