1174	    /// Delegates every call to the real `CliCommandRunner`, except `git
1175	    /// ls-remote` (used only to resolve `callisto@<version>`'s commit),
1176	    /// answered from canned output -- keeps these tests network-free without
1177	    /// faking the many other git calls `run()` legitimately makes against
1178	    /// each test's own temp repository.
1179	    struct FakeLsRemote {
1180	        stdout: &'static str,
1181	    }
1182	
1183	    impl CommandRunner for FakeLsRemote {
1184	        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
1185	            CliCommandRunner.run(program, args, cwd)
1186	        }
1187	        fn run_with_timeout(
1188	            &self,
1189	            program: &str,
1190	            args: &[&str],
1191	            cwd: &Path,
1192	            timeout: std::time::Duration,
1193	        ) -> Result<CommandOutput, CommandError> {
1194	            CliCommandRunner.run_with_timeout(program, args, cwd, timeout)
1195	        }
1196	        fn run_quiet(
1197	            &self,
1198	            program: &str,
1199	            args: &[&str],
1200	            cwd: &Path,
1201	            timeout: std::time::Duration,
1202	        ) -> Result<CommandOutput, CommandError> {
1203	            if program == "git" && args.first() == Some(&"ls-remote") {
1204	                return Ok(CommandOutput {
1205	                    exit_code: Some(0),
1206	                    stdout: self.stdout.to_owned(),
1207	                    stderr: String::new(),
1208	                });
1209	            }
1210	            CliCommandRunner.run_quiet(program, args, cwd, timeout)
1211	        }
1212	        fn run_with_stdin(
1213	            &self,
1214	            program: &str,
1215	            args: &[&str],
1216	            cwd: &Path,
1217	            stdin: &[u8],
1218	        ) -> Result<CommandOutput, CommandError> {
1219	            CliCommandRunner.run_with_stdin(program, args, cwd, stdin)
1220	        }
1221	    }
