  47	/// Asks the operator questions; a scripted implementation drives tests.
  48	pub trait Prompter {
  49	    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError>;
  50	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
  51	    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError>;
  52	}
