  56	impl Prompter for TerminalPrompter {
  57	    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError> {
  58	        Ok(Select::new().with_prompt(prompt).items(items).default(0).interact()?)
  59	    }
  60	
  61	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
  62	        Ok(Confirm::new().with_prompt(prompt).default(default).interact()?)
  63	    }
  64	
  65	    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError> {
  66	        let mut input = Input::<String>::new().with_prompt(prompt);
  67	        if let Some(default) = default {
  68	            input = input.default(default.to_owned());
  69	        }
  70	        Ok(input.interact_text()?)
  71	    }
  72	}
