 255	/// Rejects flag combinations invalid regardless of workspace facts.
 256	fn validate_flags(args: &InitArgs) -> Result<(), CliError> {
 257	    if args.workflow && args.no_workflow {
 258	        return Err(CliError::InitWorkflowFlagsConflict);
 259	    }
 260	    if args.artifact_targets.is_empty() {
 261	        if args.forge_repository.is_some() {
 262	            return Err(CliError::InitFlagRequiresArtifactTarget {
 263	                flag: "forge-repository",
 264	            });
 265	        }
 266	        if args.product_package.is_some() {
 267	            return Err(CliError::InitFlagRequiresArtifactTarget {
 268	                flag: "product-package",
 269	            });
 270	        }
 271	    }
 272	    Ok(())
 273	}
