 437	    /// Answers in order; records each prompt with how much output preceded it.
 438	    struct Scripted {
 439	        answers: VecDeque<Answer>,
 440	        asked: Vec<(String, Option<String>)>,
 441	        output: Shared,
 442	        output_at_first_prompt: Option<String>,
 443	    }
