 455	        fn next(&mut self, prompt: &str, default: Option<&str>) -> Answer {
 456	            self.output_at_first_prompt.get_or_insert_with(|| self.output.text());
 457	            self.asked.push((prompt.to_owned(), default.map(str::to_owned)));
 458	            self.answers
 459	                .pop_front()
 460	                .unwrap_or_else(|| panic!("unexpected prompt `{prompt}`"))
 461	        }
