 472	                _ => panic!("`{prompt}` is not a select"),
 473	            }
 474	        }
 475	        fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
 476	            match self.next(prompt, Some(&default.to_string())) {
 477	                Answer::Confirm(answer) => Ok(answer),
 478	                _ => panic!("`{prompt}` is not a confirm"),
 479	            }
 480	        }
 481	        fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError> {
 482	            match self.next(prompt, default) {
 483	                Answer::Input(answer) => Ok(answer.to_owned()),
 484	                _ => panic!("`{prompt}` is not an input"),
 485	            }
 486	        }
 487	    }
