   211	            schema_version: SCHEMA_VERSION,
   212	            initialized: false,
   213	            config_path: facts.root.join("callisto.toml"),
   214	            config,
   215	            files,
   216	            diagnostics: Vec::new(),
   217	        }
   218	    } else {
   219	        if prompting && !prompter.confirm(WRITE_PROMPT, true)? {
   220	            writeln!(human, "Initialization cancelled; nothing was written.")?;
   221	            return Ok(ExitCode::SUCCESS);
   222	        }
   223	        let permit = ApplyPermit::granted_unless_dry_run(false).expect("non-dry-run permits writes");
   224	        let mut report = scaffold::write(&facts.root, &config, &permit)?;
