   309	fn missing(flag: &'static str) -> CliError {
   310	    CliError::InitMissingFlags { missing: vec![flag] }
   311	}
   312	
   313	fn collect_answers(
   314	    args: &InitArgs,
   315	    facts: &InitFacts,
   316	    prompting: bool,
   317	    prompter: &mut dyn Prompter,
   318	) -> Result<InitAnswers, CliError> {
   319	    let versioning = match args.versioning {
   320	        Some(InitVersioning::Fixed) => Versioning::Fixed,
   321	        Some(InitVersioning::Independent) => Versioning::Independent,
   322	        None if prompting => {
   323	            let choices: Vec<String> = VERSIONING_CHOICES.iter().map(|choice| (*choice).to_owned()).collect();
   324	            match prompter.select(VERSIONING_PROMPT, &choices)? {
   325	                0 => Versioning::Independent,
   326	                _ => Versioning::Fixed,
   327	            }
   328	        }
   329	        None => return Err(missing("--versioning")),
   330	    };
   331	    let no_binaries = InitAnswers {
   332	        versioning,
   333	        binaries: None,
   334	    };
   335	
   336	    let binaries: Vec<&InitPackage> = facts.binary_packages().collect();
   337	    if binaries.is_empty() && !args.artifact_targets.is_empty() {
   338	        return Err(GraphError::InitNoBinaryPackage.into());
   339	    }
   340	    let requested_product = args
   341	        .product_package
   342	        .as_deref()
   343	        .map(|name| facts.product_package(name))
   344	        .transpose()?;
   345	    if binaries.is_empty() {
   346	        return Ok(no_binaries);
   347	    }
   348	    // No `origin`: the forge question below has nothing to validate a repository against, so
   349	    // shipping is never offered (skips straight to `no_binaries`); `--artifact-target` without
   350	    // `origin` is already rejected up front in `run`.
   351	    let ship = !args.artifact_targets.is_empty()
   352	        || (facts.origin.is_some() && prompting && prompter.confirm(SHIP_PROMPT, false)?);
   353	    if !ship {
   354	        return Ok(no_binaries);
   355	    }
   356	
   357	    let product = match (requested_product, binaries.as_slice()) {
   358	        (Some(product), _) => product,
   359	        (None, [only]) => only,
   360	        (None, _) if prompting => {
   361	            let ids: Vec<String> = binaries.iter().map(|package| package.id.clone()).collect();
   362	            binaries[prompter.select(PRODUCT_PROMPT, &ids)?]
   363	        }
   364	        (None, _) => return Err(missing("--product-package")),
   365	    };
   366	
   367	    let forge_repository = match &args.forge_repository {
   368	        Some(value) => scaffold::forge_repository(facts, value)?,
   369	        None if prompting => {
   370	            let detected = facts.origin_repository.as_ref().map(|repository| repository.as_slug());
   371	            scaffold::forge_repository(facts, &prompter.input(FORGE_PROMPT, detected.as_deref())?)?
   372	        }
   373	        None => return Err(missing("--forge-repository")),
   374	    };
   375	
   376	    let targets = if args.artifact_targets.is_empty() {
   377	        loop {
   378	            let answer = prompter.input(TARGETS_PROMPT, None)?;
   379	            let targets: Vec<String> = answer.split(',').map(str::trim).map(str::to_owned).collect();
   380	            if targets.iter().all(|target| target.is_empty()) {
   381	                // Nothing meaningful submitted: re-ask rather than error.
   382	                continue;
   383	            }
   384	            break targets;
   385	        }
   386	    } else {
   387	        args.artifact_targets.clone()
   388	    };
   389	    let targets = scaffold::validate_targets(&targets)?;
   390	
   391	    Ok(InitAnswers {
   392	        versioning,
   393	        binaries: Some(BinaryRelease {
   394	            product: product.id.clone(),
   395	            forge_repository,
   396	            targets,
   397	        }),
   398	    })
   399	}
