/// The workflow shape `init` generates for this workspace and answers.
///
/// # Errors
///
/// The workspace has a shape no generated workflow covers.
pub fn workflow_shape(facts: &InitFacts, answers: &InitAnswers) -> Result<WorkflowShape, WorkflowUnsupported> {
    if facts.has_maturin_targets {
        Err(WorkflowUnsupported::Maturin)
    } else if facts.has_platform_packages && !facts.has_napi_targets {
        Err(WorkflowUnsupported::PlatformPackagesWithoutNapiTargets)
    } else if answers.binaries.is_some() || facts.has_platform_packages {
        Ok(WorkflowShape::BuildMatrix)
    } else {
        Ok(WorkflowShape::Simple)
    }
}

/// Where [`default_branch`]'s branch name came from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DefaultBranchSource {
    /// The local `refs/remotes/origin/HEAD` ref, set by `git clone` or `git remote set-head`.
    OriginHead,
    /// `git ls-remote --symref origin HEAD`, queried when the local ref above is unset.
    RemoteHead,
    /// The branch currently checked out: no remote reports a HEAD (e.g. `origin` is unset).
    CurrentBranch,
    /// No remote and no checked-out branch (e.g. a fresh repo with no commits): `main`.
// Braces are literal here (not a `format!` template) so `${{ ... }}` GitHub
// Actions expressions need no escaping.
const WORKFLOW_TEMPLATE: &str = "name: Release

on:
  push:
    branches: [__BRANCH__]

permissions: {}

jobs:
  version-pr:
    runs-on: ubuntu-latest
    permissions: {contents: write, pull-requests: write}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {fetch-depth: 0, persist-credentials: false}
      - uses: orin-dx/callisto/.github/actions/callisto-action@__COMMIT__ # callisto@__VERSION__
        with: {mode: version-pr, branch: __BRANCH__}
        env:
          GH_TOKEN: ${{ github.token }}

  release:
    runs-on: ubuntu-latest
    permissions: {contents: write, id-token: write}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {fetch-depth: 0} # zizmor: ignore[artipacked] tag push needs persisted credentials
      - uses: orin-dx/callisto/.github/actions/callisto-action@__COMMIT__ # callisto@__VERSION__
        with: {mode: release}
        __RELEASE_ENV__
";

// A raw string (not a `format!` template) for the same reason as `WORKFLOW_TEMPLATE`.
const MATRIX_WORKFLOW_TEMPLATE: &str = r#"name: Release

on:
  push:
    branches: [__BRANCH__]

permissions: {}

defaults:
  run:
    shell: bash

jobs:
  version-pr:
    runs-on: ubuntu-latest
    permissions: {contents: write, pull-requests: write}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {fetch-depth: 0, persist-credentials: false}
      - uses: orin-dx/callisto/.github/actions/callisto-action@__COMMIT__ # callisto@__VERSION__
        with: {mode: version-pr, branch: __BRANCH__}
        env:
          GH_TOKEN: ${{ github.token }}

  plan:
    runs-on: ubuntu-latest
    permissions: {contents: read}
    outputs:
      release: ${{ steps.decision.outputs.release }}
      matrix: ${{ steps.matrix.outputs.matrix }}
      has_napi: ${{ steps.matrix.outputs.has_napi }}
      has_artifacts: ${{ steps.matrix.outputs.has_artifacts }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {fetch-depth: 0, persist-credentials: false}
      # Content precondition, not release detection: `release plan` requires this commit to write its decision.
    }

    // Validates the generated workflow's YAML/GHA-schema well-formedness
    // (actionlint) and security posture (zizmor); skips a check whose tool
    // isn't installed rather than failing on an environment gap.
    #[test]
    fn render_workflow_passes_actionlint_and_zizmor_when_available() {
        let mut facts = cargo_only_facts();
        facts.ecosystems = BTreeSet::from([Ecosystem::Cargo, Ecosystem::Npm, Ecosystem::Pypi]);
        lint_workflow(&render_workflow_0_8_0(&facts, "main"));
        lint_workflow(&render_matrix_workflow());
    }

    fn lint_workflow(workflow: &str) {
        let dir = tempfile::tempdir().unwrap();
        let workflows_dir = dir.path().join(".github/workflows");
        std::fs::create_dir_all(&workflows_dir).unwrap();
        let path = workflows_dir.join("callisto-release.yml");
        std::fs::write(&path, workflow).unwrap();

        match std::process::Command::new("actionlint").arg(&path).output() {
            Ok(output) => assert!(
                output.status.success(),
                "actionlint:\n{}{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            ),
            Err(_) => eprintln!("actionlint not installed; skipping that check"),
        }
        match std::process::Command::new("zizmor")
            .args(["--offline", path.to_str().unwrap()])
            .output()
        {
            Ok(output) => assert!(
                output.status.success(),
                "zizmor:\n{}{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            ),
            Err(_) => eprintln!("zizmor not installed; skipping that check"),
        }
    }

