 12	/// Serializes any `Report` value to the one JSON success envelope every
 13	/// command shares: `{schemaVersion, command, dryRun, ...payload,
 14	/// diagnostics}`. `command` comes from `R::COMMAND`, `schemaVersion` from
 15	/// the payload's own `Report::schema_version()` (re-inserted at the top
 16	/// level rather than left flattened, so it appears exactly once). Callers
 17	/// pass their `Report` to this function instead of hand-building a JSON envelope.
 18	pub fn emit_report<W: io::Write, R: callisto_model::Report>(w: &mut W, val: &R, dry_run: bool) -> io::Result<()> {
 19	    let mut value = serde_json::to_value(val)?;
 20	    if let serde_json::Value::Object(map) = &mut value {
 21	        map.insert("schemaVersion".to_string(), serde_json::json!(val.schema_version()));
 22	        map.insert("command".to_string(), serde_json::json!(R::COMMAND));
 23	        map.insert("dryRun".to_string(), serde_json::json!(dry_run));
 24	    }
 25	    let text = serde_json::to_string_pretty(&value)?;
 26	    writeln!(w, "{text}")
 27	}
