 55	/// (`callisto add`'s step prompts), which must stay off stdout so a script
 56	/// piping stdout never sees prompt text mixed into a report or changeset preview.
 57	pub fn prompt_line(line: &str) {
 58	    eprintln!("{line}");
 59	}
 60	
 61	pub fn log_line(format: OutputFormat, line: &str) -> io::Result<()> {
 62	    match format {
 63	        OutputFormat::Json => {
 64	            eprintln!("{line}");
 65	            Ok(())
 66	        }
 67	        OutputFormat::Text => emit_line(line),
 68	    }
 69	}
