//! Proves `release-pr commit-plan`'s output is byte-faithful to what Git
//! itself would commit: applying the plan's additions/deletions onto a
//! fresh checkout of `--base-commit` must reproduce the exact tree the
//! staged index actually held when the plan was built.

mod common;

use std::fs;
use std::process::Command;

use base64::engine::general_purpose::STANDARD as BASE64;
use base64::Engine as _;
use common::setup_polyglot_git_repo;

fn bin() -> &'static str {
    env!("CARGO_BIN_EXE_callisto")
}

fn git(root: &std::path::Path, args: &[&str]) -> std::process::Output {
    Command::new("git")
        .args(args)
        .current_dir(root)
        .output()
        .unwrap_or_else(|e| panic!("failed to spawn git {args:?}: {e}"))
}

fn git_ok(root: &std::path::Path, args: &[&str]) -> String {
    let out = git(root, args);
    assert!(
        out.status.success(),
        "git {args:?} failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8(out.stdout).unwrap().trim().to_string()
}

#[test]
fn commit_plan_reproduces_git_write_tree() {
    let dir = setup_polyglot_git_repo();
    let root = dir.path();
    let base_sha = git_ok(root, &["rev-parse", "HEAD"]);

    // Stage an addition, a modification, a deletion, and a CRLF file.
    fs::write(root.join("NEW_FILE.txt"), b"brand new\n").unwrap();
    fs::write(
        root.join("crates/core/src/lib.rs"),
        b"pub fn hello() {\n    println!(\"hi\");\n}\n",
    )
    .unwrap();
    fs::remove_file(root.join("packages/web/package.json")).unwrap();
    fs::write(root.join("crlf.txt"), b"line one\r\nline two\r\n").unwrap();
    let out = git(root, &["add", "-A"]);
    assert!(out.status.success());

    let expected_tree = git_ok(root, &["write-tree"]);

    let out = Command::new(bin())
        .args([
            "--cwd",
            root.to_str().unwrap(),
            "--format",
            "json",
            "release-pr",
            "commit-plan",
            "--base-commit",
            &base_sha,
            "--message",
            "test commit",
        ])
        .output()
        .unwrap_or_else(|e| panic!("failed to spawn callisto release-pr commit-plan: {e}"));
    assert!(
        out.status.success(),
        "commit-plan failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    let plan: serde_json::Value = serde_json::from_slice(&out.stdout).unwrap();

    // Reconstruct the base tree into a standalone directory via `git
    // archive`, apply the plan's additions/deletions, and compare trees --
    // this never touches the original repo's own (already-staged) index.
    let recon = tempfile::tempdir().unwrap();
    let archive_out = git(root, &["archive", &base_sha]);
    assert!(archive_out.status.success());
    let tar_status = {
        let mut child = Command::new("tar")
            .args(["-x", "-C", recon.path().to_str().unwrap()])
            .stdin(std::process::Stdio::piped())
            .spawn()
            .unwrap();
        use std::io::Write;
        child.stdin.take().unwrap().write_all(&archive_out.stdout).unwrap();
        child.wait().unwrap()
    };
    assert!(tar_status.success());
    callisto_fixtures::git::init_repo(recon.path());

    for addition in plan["additions"].as_array().unwrap() {
        let path = addition["path"].as_str().unwrap();
        let contents = BASE64.decode(addition["contentsBase64"].as_str().unwrap()).unwrap();
        fs::write(&script, b"#!/bin/sh\necho hi\n").unwrap();
        let mut perms = fs::metadata(&script).unwrap().permissions();
        perms.set_mode(0o755);
        fs::set_permissions(&script, perms).unwrap();
    }
    #[cfg(not(unix))]
    {
        fs::write(root.join("script.sh"), b"#!/bin/sh\necho hi\n").unwrap();
    }
    let out = git(root, &["add", "-A"]);
    assert!(out.status.success());

    let out = Command::new(bin())
        .args([
            "--cwd",
            root.to_str().unwrap(),
            "--format",
            "json",
            "release-pr",
            "commit-plan",
            "--base-commit",
            &base_sha,
            "--message",
            "test commit",
        ])
        .output()
        .unwrap_or_else(|e| panic!("failed to spawn callisto release-pr commit-plan: {e}"));

    #[cfg(unix)]
    {
        assert!(
            !out.status.success(),
            "an executable-bit addition must be refused, not silently downgraded"
        );
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(
            stderr.contains("E150") || stderr.to_lowercase().contains("mode"),
            "expected an UnsupportedFileMode-shaped error, got: {stderr}"
        );
    }
}
#!/usr/bin/env bash
# Black-box coverage for the exact release-PR action executable. The fake
# process boundary proves the script executes only Callisto's closed decision
# set and only the forge commit API (never `git push`); Rust tests cover
# decision policy itself.
#
# This stubs `callisto` with hand-written JSON fixtures, so it cannot catch a
# mismatch between what the real binary serializes and what this script's jq
# expressions expect -- see test_release_pr_decide_binary_contract.sh, which
# calls the compiled binary, for that check.
set -euo pipefail

action_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
script="$action_dir/scripts/create-or-update-release-pr.sh"

run_case() {
  local prs="$1" decision="$2" label_exists="${3:-true}"
  local calls_file output_file harness verify_count_file
  calls_file="$(mktemp)"
  output_file="$(mktemp)"
  verify_count_file="$(mktemp)"
  harness="$(mktemp)"
  rm -f "$verify_count_file"

  {
    cat <<'STUBS'
callisto() {
  echo "callisto $*" >> "$CALLS_FILE"
  if [[ " $* " == *' release-pr decide '* ]]; then printf '%s\n' "$DECISION"; return 0; fi
  if [[ " $* " == *' release-pr verify '* ]]; then
    local n
    n=$(( $(cat "$VERIFY_COUNT_FILE" 2>/dev/null || echo 0) + 1 ))
    echo "$n" > "$VERIFY_COUNT_FILE"
    if [[ "$VERIFY_FAIL_AT" != 0 && "$n" == "$VERIFY_FAIL_AT" ]]; then return 1; fi
    return 0
  fi
  if [[ " $* " == *' release-pr commit-plan '* ]]; then
    local out='' prev=''
    for a in "$@"; do
      [[ "$prev" == '--out' ]] && out="$a"
      prev="$a"
    done
    printf '%s\n' "$COMMIT_PLAN" > "$out"
    return "$COMMIT_PLAN_CODE"
  fi
  case "$1" in
    matrix) printf '%s\n' '{"platformTargets":[]}' ;;
    compose-pr-body) echo 'composed release body' ;;
    version) return 0 ;;
    *) echo "unexpected callisto invocation: $*" >&2; return 97 ;;
  printf '%s\n' '---outputs---'
  cat "$output_file"
  rm -f "$calls_file" "$output_file" "$harness" "$verify_count_file"
}

