        with: {mode: version-pr, branch: __BRANCH__}
        env:
          GH_TOKEN: ${{ github.token }}

  release:
    runs-on: ubuntu-latest
    permissions: {contents: write, id-token: write}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {fetch-depth: 0} # zizmor: ignore[artipacked] tag push needs persisted credentials
      - uses: orin-dx/callisto/.github/actions/callisto-action@__COMMIT__ # callisto@__VERSION__
        with: {mode: release}
        __RELEASE_ENV__
";

// A raw string (not a `format!` template) for the same reason as `WORKFLOW_TEMPLATE`.
const MATRIX_WORKFLOW_TEMPLATE: &str = r#"name: Release

on:
  push:
    branches: [__BRANCH__]

permissions: {}

defaults:
  run:
    shell: bash

jobs:
  version-pr:
    runs-on: ubuntu-latest
    permissions: {contents: write, pull-requests: write}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {fetch-depth: 0, persist-credentials: false}
      - uses: orin-dx/callisto/.github/actions/callisto-action@__COMMIT__ # callisto@__VERSION__
        with: {mode: version-pr, branch: __BRANCH__}
        env:
          GH_TOKEN: ${{ github.token }}

  plan:
    runs-on: ubuntu-latest
    permissions: {contents: read}
    outputs:
      release: ${{ steps.decision.outputs.release }}
      matrix: ${{ steps.matrix.outputs.matrix }}
      has_napi: ${{ steps.matrix.outputs.has_napi }}
      has_artifacts: ${{ steps.matrix.outputs.has_artifacts }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {fetch-depth: 0, persist-credentials: false}
      # Content precondition, not release detection: `release plan` requires this commit to write its decision.
      - name: Check for a release decision
        id: decision
        run: |
          set -euo pipefail
          release=false
          if git rev-parse --verify --quiet HEAD^ > /dev/null &&
            git diff-tree --no-commit-id --name-only --diff-filter=AM -r HEAD^ HEAD | grep -qxF .callisto/release-decision.json; then
            release=true
          fi
          echo "release=$release" >> "$GITHUB_OUTPUT"
      - if: steps.decision.outputs.release == 'true'
        uses: orin-dx/callisto/.github/actions/setup-callisto@__COMMIT__ # callisto@__VERSION__
        with: {version: callisto@__VERSION__}
      - name: Plan the release
        if: steps.decision.outputs.release == 'true'
        run: |
          set -euo pipefail
          mkdir -p "$RUNNER_TEMP/release-intent"
          callisto release plan --from-release-commit "$GITHUB_SHA" --decision .callisto/release-decision.json \
            --orchestration-revision "$GITHUB_SHA" --artifact-repository "$GITHUB_REPOSITORY" \
            --out "$RUNNER_TEMP/release-intent/release-intent.json"
      - name: Build the matrix from napi targets and artifact slots
        id: matrix
        if: steps.decision.outputs.release == 'true'
        run: |
          set -euo pipefail
          report="$RUNNER_TEMP/matrix.json"
          callisto --format json matrix > "$report"
          napi=$(jq -c '[.platformTargets[] | select(.kind=="napi") | .targets[] | {kind: "napi"} + .]' "$report")
          slots=$(jq -c --slurpfile report "$report" '[.artifactSlots[] as $slot
            | ([$report[0].platformTargets[] | select(.kind=="cargo") | .targets[]
                | select(.artifactName == $slot.assetName and .triple == $slot.platform)] | first
              // error("callisto matrix has no entry for artifact slot \($slot.assetName)"))
            | {kind: "cargo"} + .]' "$RUNNER_TEMP/release-intent/release-intent.json")
          {
            echo "matrix=$(jq -cn --argjson napi "$napi" --argjson slots "$slots" '$napi + $slots')"
            echo "has_napi=$(jq 'length > 0' <<< "$napi")"
            echo "has_artifacts=$(jq 'length > 0' <<< "$slots")"
          } >> "$GITHUB_OUTPUT"
      - if: steps.decision.outputs.release == 'true'
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: release-intent
          path: ${{ runner.temp }}/release-intent
          if-no-files-found: error

  build:
    needs: plan
    if: needs.plan.outputs.release == 'true' && needs.plan.outputs.matrix != '[]'
    strategy:
      fail-fast: false
      matrix:
        include: ${{ fromJSON(needs.plan.outputs.matrix) }}
    runs-on: ${{ matrix.hostRunner }}
    permissions: {contents: read, id-token: write, attestations: write}
    env:
      KIND: ${{ matrix.kind }}
      TRIPLE: ${{ matrix.triple }}
      USE_CROSS: ${{ matrix.useCross }}
      PACKAGE_DIR: ${{ matrix.packageDir }}
      PACKAGE: ${{ matrix.packageName }}
      MANIFEST_PATH: ${{ matrix.manifestPath }}
      ASSET: ${{ matrix.artifactName }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {persist-credentials: false}
      - name: Install the Rust target
        run: |
          set -euo pipefail
          rustup target add "$TRIPLE"
          if [[ "$USE_CROSS" == true ]]; then cargo install cross --locked --version 0.2.5; fi
      - name: Build the napi addon
        if: matrix.kind == 'napi'
        run: |
          set -euo pipefail
          args=(--platform --release --target "$TRIPLE" --output-dir "$RUNNER_TEMP/napi-out")
          if [[ "$USE_CROSS" == true ]]; then args+=(--use-cross); fi
          if [[ -n "$MANIFEST_PATH" ]]; then args+=(--manifest-path "$GITHUB_WORKSPACE/$MANIFEST_PATH"); fi
          (cd "${PACKAGE_DIR:-.}" && npx --yes --package @napi-rs/cli@3.10.4 napi build "${args[@]}")
      - if: matrix.kind == 'napi'
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: napi-${{ matrix.artifactName }}
          path: ${{ runner.temp }}/napi-out/*.node
          if-no-files-found: error
      - name: Build and archive the release artifact
        if: matrix.kind == 'cargo'
        run: |
          set -euo pipefail
          cargo_bin=cargo
          if [[ "$USE_CROSS" == true ]]; then cargo_bin=cross; fi
          "$cargo_bin" build --release --locked --target "$TRIPLE" --package "$PACKAGE"
          metadata=$(cargo metadata --no-deps --format-version 1)
          target_dir=$(jq -r .target_directory <<< "$metadata")
          temp=$RUNNER_TEMP
          if command -v cygpath > /dev/null; then target_dir=$(cygpath -u "$target_dir"); temp=$(cygpath -u "$temp"); fi
          case "$TRIPLE" in *windows*) suffix=.exe ;; wasm32-*) suffix=.wasm ;; *) suffix= ;; esac
          stage="$temp/release-stage"
          out="$temp/release-assets"
          mkdir -p "$stage" "$out"
          jq -r --arg package "$PACKAGE" '.packages[] | select(.name == $package) | .targets[]
            | select(.kind | index("bin")) | .name' <<< "$metadata" | while IFS= read -r bin; do
            cp "$target_dir/$TRIPLE/release/$bin$suffix" "$stage/"
          done
          if [[ -z "$(ls -A "$stage")" ]]; then
            echo "::error::$PACKAGE builds no binary target for $TRIPLE"
            exit 1
          fi
          cd "$stage"
          case "$ASSET" in
            *.tar.gz | *.tgz) tar -czf "$out/$ASSET" ./* ;;
            *.tar.xz) tar -cJf "$out/$ASSET" ./* ;;
            *.zip) if command -v zip > /dev/null; then zip -q "$out/$ASSET" ./*; else 7z a -bd "$out/$ASSET" ./* > /dev/null; fi ;;
            *)
              binaries=(./*)
              if [[ ${#binaries[@]} -ne 1 ]]; then
                echo "::error::$ASSET is not an archive name, but $PACKAGE builds ${#binaries[@]} binaries"
                exit 1
              fi
              cp "${binaries[0]}" "$out/$ASSET"
              ;;
          esac
      - if: matrix.kind == 'cargo'
        uses: actions/attest-build-provenance@4d101475d8b20a2381f78447822ac1eab6504dd8 # v4.2.2
        with:
          subject-path: ${{ runner.temp }}/release-assets/${{ matrix.artifactName }}
      - if: matrix.kind == 'cargo'
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: asset-${{ matrix.artifactName }}
          path: ${{ runner.temp }}/release-assets/${{ matrix.artifactName }}
          if-no-files-found: error

  execute:
    needs: [plan, build]
    # A skipped build blocks only when the matrix had entries to build.
    if: >-
      !cancelled() && needs.plan.outputs.release == 'true' &&
      (needs.build.result == 'success' || (needs.build.result == 'skipped' && needs.plan.outputs.matrix == '[]'))
    runs-on: ubuntu-latest
    concurrency: {group: callisto-release-execute, cancel-in-progress: false}
    permissions: {contents: write, id-token: write, attestations: read}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with: {fetch-depth: 0} # zizmor: ignore[artipacked] tag push needs persisted credentials
      - uses: orin-dx/callisto/.github/actions/setup-callisto@__COMMIT__ # callisto@__VERSION__
        with: {version: callisto@__VERSION__}
      # Downloads land under $RUNNER_TEMP: `release execute` requires a clean worktree.
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-intent
          path: ${{ runner.temp }}/release-intent
      - if: needs.plan.outputs.has_napi == 'true'
        uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          pattern: napi-*
          merge-multiple: true
          path: ${{ runner.temp }}/napi-artifacts
      - name: Place napi artifacts
        if: needs.plan.outputs.has_napi == 'true'
        run: |
          set -euo pipefail
          callisto --format json matrix \
            | jq -r '[.platformTargets[] | select(.kind=="napi") | .targets[].packageDir] | unique[]' \
            | while IFS= read -r dir; do
              npx --yes --package @napi-rs/cli@3.10.4 napi artifacts --cwd "${dir:-.}" --output-dir "$RUNNER_TEMP/napi-artifacts"
            done
      - if: needs.plan.outputs.has_artifacts == 'true'
        uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          pattern: asset-*
          merge-multiple: true
          path: ${{ runner.temp }}/release-assets
      - name: Write the artifact manifest
        if: needs.plan.outputs.has_artifacts == 'true'
        run: |
          set -euo pipefail
          callisto release artifact-manifest --intent "$RUNNER_TEMP/release-intent/release-intent.json" \
            --artifact-dir "$RUNNER_TEMP/release-assets" --out "$RUNNER_TEMP/release-manifest.json"
      - name: Execute the release
        run: |
          set -euo pipefail
          args=(--intent "$RUNNER_TEMP/release-intent/release-intent.json" --receipt "$RUNNER_TEMP/release-receipt.json"
            --orchestration-revision "$GITHUB_SHA")
          if [[ -f "$RUNNER_TEMP/release-manifest.json" ]]; then
            args+=(--artifact-manifest "$RUNNER_TEMP/release-manifest.json" --artifact-dir "$RUNNER_TEMP/release-assets")
          fi
          callisto release execute "${args[@]}"
        __RELEASE_ENV__
"#;

/// Resolves `callisto@<version>`'s commit SHA on `orin-dx/callisto`'s remote.
///
/// GitHub's runner splits a `uses:` reference at the LAST `@` in the whole
/// string (`ActionManifestManagerWrapper.ParseActionReference` in
/// `actions/runner`), so a ref that itself contains `@` -- like the
/// `callisto@<version>` tag this project releases under -- can never be
/// written directly as `owner/repo/path@callisto@<version>`: the split lands
/// inside the ref, not before it, and resolution fails. The generated
/// workflow pins to this tag's resolved commit instead, like every other
/// external action reference in this repository.
///
/// # Errors
///
/// The remote is unreachable, or `callisto@<version>` is not a published tag.
pub fn resolve_release_commit<R: CommandRunner>(runner: &R, root: &Path, version: &str) -> Result<String, GraphError> {
    const ENDPOINT: &str = "https://github.com/orin-dx/callisto.git";
    let reference = format!("refs/tags/callisto@{version}");
    // The peeled ref resolves an annotated tag to its commit; a lightweight
    // tag has no peeled line, and its own SHA already is the commit.
    let peeled = format!("{reference}^{{}}");
    // A transport-level failure (git not found, timed out, ...) keeps its
    // real cause via `GraphError::Command`; only a clean run that still
    // can't find the tag becomes `InitWorkflowVersionUnresolved`.
    let output = runner.run_quiet(
        programs::GIT,
        &["ls-remote", ENDPOINT, &reference, &peeled],
        root,
        timeouts::GIT_LS_REMOTE,
    )?;
    let unresolved = || GraphError::InitWorkflowVersionUnresolved {
        version: version.to_owned(),
    };
    if output.exit_code != Some(0) {
        return Err(unresolved());
    }
    let mut tag_object = None;
    let mut commit = None;
    for line in output.stdout.lines() {
        let Some((sha, found)) = line.split_once('\t') else {
            continue;
        };
        match found.trim() {
            found if found == peeled => commit = Some(sha.trim().to_owned()),
            found if found == reference => tag_object = Some(sha.trim().to_owned()),
            _ => {}
        }
    }
    commit.or(tag_object).ok_or_else(unresolved)
}

/// Renders the release workflow for `shape`.
///
/// `commit` pins the generated `orin-dx/callisto` action references to the
/// resolved commit of `callisto@<version>` (see [`resolve_release_commit`]);
/// `version` names the CLI `setup-callisto` installs and a trailing comment.
pub fn render_workflow(facts: &InitFacts, shape: WorkflowShape, branch: &str, commit: &str, version: &str) -> String {
    let mut secrets = Vec::new();
    if facts.ecosystems.contains(&Ecosystem::Cargo) {
        secrets.push("CARGO_REGISTRY_TOKEN: ${{ secrets.CARGO_REGISTRY_TOKEN }}".to_owned());
    }
    if facts.ecosystems.contains(&Ecosystem::Npm) {
        secrets.push("NPM_TOKEN: ${{ secrets.NPM_TOKEN }}".to_owned());
        // Uses the job's id-token: write; npm publishes no provenance without it.
        secrets.push("NPM_CONFIG_PROVENANCE: \"true\"".to_owned());
    }
    if facts.ecosystems.contains(&Ecosystem::Pypi) {
        secrets.push("PYPI_TOKEN: ${{ secrets.PYPI_TOKEN }}".to_owned());
    }
    secrets.push("GH_TOKEN: ${{ github.token }}".to_owned());
    let env_lines: Vec<String> = secrets.iter().map(|line| format!("          {line}")).collect();
    let release_env = format!("env:\n{}", env_lines.join("\n"));

    let template = match shape {
        WorkflowShape::Simple => WORKFLOW_TEMPLATE,
        WorkflowShape::BuildMatrix => MATRIX_WORKFLOW_TEMPLATE,
    };
    template
        .replace("__BRANCH__", branch)
        .replace("__COMMIT__", commit)
        .replace("__VERSION__", version)
        .replace("        __RELEASE_ENV__", &format!("        {release_env}"))
}

/// Errors if a workflow file already exists at [`workflow_path`], without writing.
///
/// # Errors
///
/// A file already exists at that path.
pub fn ensure_workflow_absent(root: &Path) -> Result<(), GraphError> {
    let path = workflow_path(root);
    if path.exists() {
        return Err(GraphError::InitWorkflowExists { path });
    }
    Ok(())
}

/// Writes the generated release workflow.
///
/// # Errors
///
/// A workflow file already exists at [`workflow_path`], or the write fails.
pub fn write_workflow(root: &Path, content: &str, permit: &ApplyPermit) -> Result<(), GraphError> {
    ensure_workflow_absent(root)?;
    let path = workflow_path(root);
    callisto_model::atomic::atomic_write(&path, content, permit).map_err(io_err(&path))
}

#[cfg(test)]
mod tests {
    use std::path::Path;
"}}

