# Runs `callisto release` (mode: release) and fills published/publishedPackages
# from its receipt; callisto release's own idempotency makes a redundant run a no-op.
set -euo pipefail

cd "$INPUT_CWD"

receipt="$(mktemp -d)/release-receipt.json"
output=$(callisto --format json release --receipt "$receipt")

if jq -e '.nothingToRelease == true' <<< "$output" > /dev/null; then
  echo 'published=false' >> "$GITHUB_OUTPUT"
  echo 'publishedPackages=[]' >> "$GITHUB_OUTPUT"
  echo '::notice::Nothing to release.'
  exit 0
fi

packages=$(jq -c '[
    .outcomes[]
    | select(.outcome.kind == "published" and (.operation.role.kind == "registryPublish" or .operation.role.kind == "platformPublish"))
    | .operation.package
  ] | unique' "$receipt")
published=$(jq -r 'length > 0' <<< "$packages")
{
  echo "published=$published"
  echo "publishedPackages=$packages"
} >> "$GITHUB_OUTPUT"
use callisto_model::{CommandRunner, Diagnostic, DiagnosticCode, DiagnosticSeverity, MatrixReport, PackageId};

use crate::error::GraphError;
use crate::matrix::{
    add_release_artifact_groups, build_matrix_report, MatrixPackageInput, NapiCrate, ReleaseArtifactInput,
};
use crate::resolver::DependencyResolver;
use crate::Workspace;

#[derive(Clone, Debug, Default)]
pub struct MatrixOptions {
    /// When Some, restrict the report to exactly this one registered package.
    /// Accepts a bare name -- resolved only when it matches exactly one
    /// registered package (`GraphError::AmbiguousName` otherwise, listing
    /// the qualified candidates) -- or an ecosystem-qualified id
    /// (`cargo/foo`, `npm/foo`). Err(GraphError::UnknownPackage) when no
    /// registered package matches. Resolved through
    /// [`crate::IdentityIndex::resolve`], the one selector resolver shared
    /// with every other package-selecting surface.
    pub package: Option<String>,
    /// Resolve each napi package's addon crate into `manifestPath` (E204 when not exactly one).
    pub napi_crates: bool,
}

pub fn matrix<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    opts: &MatrixOptions,
) -> Result<MatrixReport, GraphError> {
    let all_packages: Vec<&callisto_model::Package> = ws.graph.packages().collect();

    let selected = opts
        .package
        .as_deref()
        .map(|raw| resolve_selected_package(&all_packages, &ws.identity, raw))
        .transpose()?;

    let inputs: Vec<MatrixPackageInput> = all_packages
        .iter()
        .filter(|p| selected.as_ref().is_none_or(|id| p.id == *id))
        .map(|p| {
            let dir_rel = package_dir_rel(p);
            MatrixPackageInput {
                id: p.id.clone(),
                dir_abs: ws.root.join(&dir_rel),
                dir_rel,
                name: p.id.name().to_string(),
            }
        })
        .collect();

    let napi_crates = opts
        .napi_crates
        .then(|| workspace_napi_crates(ws, &all_packages))
        .transpose()?;
    let mut report = build_matrix_report(&inputs, napi_crates.as_deref())?;
    let mut artifacts = Vec::new();
    for artifact in ws
        .config
        .product_release
        .iter()
        .flat_map(|release| &release.artifacts)
        .filter(|artifact| artifact.package.ecosystem() == Some(callisto_model::Ecosystem::Cargo))
        .filter(|artifact| {
            selected
                .as_ref()
                .is_none_or(|id| ws.identity.identifies(&artifact.package, id))
        })
    {
        let resolved = all_packages.iter().find_map(|package| {
            let manifest = package
                .canonical_manifests()
                .find(|manifest| manifest.ecosystem() == callisto_model::Ecosystem::Cargo)?;
            ws.identity
                .identifies(&artifact.package, &package.id)
                .then_some((package, manifest))
        });
        let Some((package, manifest)) = resolved else {
            report.diagnostics.push(Diagnostic {
                code: DiagnosticCode::UnknownPackage,
                severity: DiagnosticSeverity::Warning,
                message: format!(
                    "`[[release.artifact]]` package `{}` (asset `{}`) is not a cargo package in this workspace; it has no matrix entry",
                    artifact.package, artifact.asset_name
                ),
                package: Some(artifact.package.clone()),
                path: None,
                escalated_by: None,
                governed_by: None,
            });
            continue;
        };
        artifacts.push(ReleaseArtifactInput {
            id: package.id.clone(),
            name: package.id.name().to_string(),
            dir_rel: manifest
                .path
                .parent()
                .map(|dir| dir.to_string_lossy().to_string())
                .unwrap_or_default(),
            target: artifact.target.clone(),
            asset_name: artifact.asset_name.clone(),
        });
    }
    add_release_artifact_groups(&mut report, &artifacts)?;
    Ok(report)
}

/// Resolves a human-typed `--package` argument (bare or ecosystem-qualified)
/// through the one selector resolver, [`crate::IdentityIndex::resolve`] --
/// a bare name is accepted only when it names exactly one package.
fn resolve_selected_package(
    all_packages: &[&callisto_model::Package],
    identity: &crate::IdentityIndex,
    raw: &str,
) -> Result<PackageId, GraphError> {
    let resolved = identity.resolve(raw)?;
    if all_packages.iter().any(|p| p.id == resolved) {
        Ok(resolved)
    } else {
        Err(GraphError::UnknownPackage { id: resolved })
    }
}

/// Every workspace cargo package that builds a napi-rs addon.
fn workspace_napi_crates<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    packages: &[&callisto_model::Package],
) -> Result<Vec<NapiCrate>, GraphError> {
    let ctx = callisto_manifests::OpenContext::for_workspace_root(&ws.root);
    let mut crates = Vec::new();
    for decl in packages
        .iter()
        .flat_map(|package| package.canonical_manifests())
        .filter(|decl| decl.format == callisto_model::ManifestFormat::CargoToml)
    {
        if let Some(lib_name) = crate::manifest_cache::open_cached(&ws.manifest_cache, decl, &ctx)?.napi_lib_name() {
            crates.push(NapiCrate {
                lib_name,
                manifest_path: decl.path.to_string_lossy().into_owned(),
            });
        }
    }
    Ok(crates)
}

fn package_dir_rel(package: &callisto_model::Package) -> String {
    package.key().map(|key| key.to_string()).unwrap_or_default()
}
//! Manifest reading and MatrixReport assembly for `callisto matrix`.
//! Private helpers only -- the public entry point is
//! `crate::commands::matrix::matrix`.

/// Per-triple CI scheduling attributes for the 18 triples
/// `crate::napi::triple_to_role` recognises today. This table is NEW code:
/// `triple_to_role`'s `ManifestRole::Platform` carries only platform/arch/abi
/// and has no concept of hostRunner/useCross, so this cannot be derived from
/// it. Returns `None` for any triple `triple_to_role` does not recognise --
/// callers must treat that as the unrecognised-triple diagnostic path, never a silent
/// default.
pub(crate) fn triple_host_runner_use_cross(triple: &str) -> Option<(&'static str, bool)> {
    Some(match triple {
        "aarch64-apple-darwin" => ("macos-latest", false),
        "x86_64-apple-darwin" => ("macos-13", false),
        "x86_64-unknown-linux-gnu" => ("ubuntu-latest", false),
        "x86_64-unknown-linux-musl" => ("ubuntu-latest", true),
        "aarch64-unknown-linux-gnu" => ("ubuntu-latest", true),
        "aarch64-unknown-linux-musl" => ("ubuntu-latest", true),
        "x86_64-pc-windows-msvc" => ("windows-latest", false),
        "i686-pc-windows-msvc" => ("windows-latest", false),
        "aarch64-pc-windows-msvc" => ("windows-latest", false),
        "armv7-unknown-linux-gnueabihf" => ("ubuntu-latest", true),
        "x86_64-unknown-freebsd" => ("ubuntu-latest", true),
        "aarch64-linux-android" => ("ubuntu-latest", true),
        "armv7-linux-androideabi" => ("ubuntu-latest", true),
        "riscv64gc-unknown-linux-gnu" => ("ubuntu-latest", true),
        "powerpc64le-unknown-linux-gnu" => ("ubuntu-latest", true),
        "s390x-unknown-linux-gnu" => ("ubuntu-latest", true),
        "wasm32-wasip1" => ("ubuntu-latest", false),
        "wasm32-unknown-unknown" => ("ubuntu-latest", false),
        _ => return None,
    })
}

/// ArtifactName embeds the package's own (already workspace-unique)
/// name alongside platform/arch/abi, mirroring napi-rs's own
/// published-package and recommended-CI-artifact convention
/// (`<name>-<platform>-<arch>[-<abi>]`, e.g. `addon-darwin-arm64`,
/// `addon-linux-x64-gnu`) rather than the raw Rust target triple -- so two
/// packages sharing a triple never collide once fed through
/// `unique_by(.artifactName)` in `.github/actions/callisto-action/action.yml`.
/// `package_name` is sanitized first: `/` is one of
/// `actions/upload-artifact`'s forbidden artifact-name characters, and an
/// npm scoped package name (e.g. `@scope/addon`) carries one -- napi-rs's
/// own published *npm registry* package name may legitimately contain `/`
/// (e.g. `@scope/addon-darwin-arm64`), but this CI-internal artifact name
/// is a different namespace with its own, stricter constraint.
pub(crate) fn artifact_name_for_package_platform(
    package_name: &str,
    platform: &str,
    arch: &str,
    abi: Option<&str>,
) -> String {
    let package_name = package_name.replace('/', "-");
    match abi {
        Some(abi) => format!("{package_name}-{platform}-{arch}-{abi}"),
        None => format!("{package_name}-{platform}-{arch}"),
    }
}

use std::path::Path;

use callisto_model::{ManifestError, ManifestFormat, ManifestRole, PlatformTarget};

use crate::error::GraphError;
use crate::napi::triple_to_role;

/// Result of reading the `napi.targets` field from a package.json. Distinct
/// from `Option<Vec<String>>` so present-but-empty vs absent is a
/// type-level distinction, not a magic-empty-vec convention.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum NapiTargetsField {
    Absent,
    Present(Vec<String>),
}

/// Reads and parses `pkg_json_path` as JSON, if it exists. `Ok(None)` when
/// the file is absent -- not every package has a `package.json`.
///
/// Callers needing more than one field out of the same `package.json` (e.g.
/// both `napi.targets` and `engines.node`, see `build_matrix_report`) must
/// call this once and pass the resulting `Value` to each field-extraction
/// function (`read_napi_targets`, `read_engines_node`) rather than letting
/// each one independently re-read and re-parse the file from disk.
pub(crate) fn parse_package_json(pkg_json_path: &Path) -> Result<Option<serde_json::Value>, GraphError> {
    if !pkg_json_path.exists() {
        return Ok(None);
    }
    let content = std::fs::read_to_string(pkg_json_path).map_err(|e| {
        GraphError::Manifest(ManifestError::Read {
            path: pkg_json_path.to_path_buf(),
            message: e.to_string(),
        })
    })?;
    let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
        GraphError::Manifest(ManifestError::Parse {
            path: pkg_json_path.to_path_buf(),
            format: ManifestFormat::PackageJson,
            message: e.to_string(),
        })
    })?;
    Ok(Some(val))
}

/// Extracts `napi.targets` from an already-parsed `package.json` value (see
/// `parse_package_json`). A missing `napi` key or missing `napi.targets` key
/// is `Absent` (no platformTargets entry). A present `napi.targets`
/// that is not a JSON array of strings is a hard error -- strict
/// policy, propagating `callisto_manifests::read_napi_targets`'s error
/// as-is; unlike `NapiTargetsIndex::load`, which `.ok()`s the same shared
/// reader to silently drop non-array values instead.
pub(crate) fn read_napi_targets(pkg_json_path: &Path, val: &serde_json::Value) -> Result<NapiTargetsField, GraphError> {
    match callisto_manifests::read_napi_targets(pkg_json_path, val).map_err(GraphError::Manifest)? {
        Some(triples) => Ok(NapiTargetsField::Present(triples)),
        None => Ok(NapiTargetsField::Absent),
    }
}

/// Builds a PlatformTarget for `triple`, combining `triple_to_role`'s
/// platform/arch/abi with this module's hostRunner/useCross/artifactName
/// table. Returns `None` when `triple` is not recognised by either --
/// callers must route that case to an UnrecognisedPlatformTriple diagnostic
/// rather than treating it as an error.
pub(crate) fn build_platform_target(triple: &str, package_dir: &str, package_name: &str) -> Option<PlatformTarget> {
    let ManifestRole::Platform { platform, arch, abi } = triple_to_role(triple)? else {
        return None;
    };
    let (host_runner, use_cross) = triple_host_runner_use_cross(triple)?;
    let artifact_name = artifact_name_for_package_platform(package_name, &platform, &arch, abi.as_deref());
    Some(PlatformTarget {
        triple: triple.to_string(),
        platform,
        arch,
        abi,
        host_runner: host_runner.to_string(),
        use_cross,
        artifact_name,
        package_dir: package_dir.to_string(),
        package_name: package_name.to_string(),
        manifest_path: None,
    })
}

/// Reads and parses `pyproject_path` as TOML, if it exists. `Ok(None)` when
pub(crate) fn napi_manifest_path(
    pkg: &MatrixPackageInput,
    pkg_json: &serde_json::Value,
    crates: &[NapiCrate],
) -> Result<Option<String>, GraphError> {
    let in_package_dir =
        |candidate: &&NapiCrate| Path::new(&candidate.manifest_path).parent() == Some(Path::new(&pkg.dir_rel));
    if crates.iter().any(|candidate| in_package_dir(&candidate)) {
        return Ok(None);
    }
    let binary_name = callisto_manifests::napi_binary_name(pkg_json);
    let matches: Vec<&NapiCrate> = crates
        .iter()
        .filter(|candidate| candidate.lib_name == binary_name)
        .collect();
    if let [only] = matches.as_slice() {
        return Ok(Some(only.manifest_path.clone()));
    }
    let listed: Vec<&NapiCrate> = if matches.is_empty() {
        crates.iter().collect()
    } else {
        matches
    };
    Err(GraphError::NapiCrateUnresolved {
        package: pkg.id.clone(),
        binary_name,
        candidates: listed
            .iter()
            .map(|candidate| format!("{} (lib `{}`)", candidate.manifest_path, candidate.lib_name))
            .collect(),
    })
}

/// Reads engines.node (npm) and requires-python (python) from
/// `package_dir_abs`'s already-parsed manifest values, in that order, so
/// callers preserve the npm-before-python ordering without
/// a separate sort step. `pkg_json_val`/`pyproject_val` are shared with
/// `assemble_platform_target_group` (see `select_platform_target_source`'s
/// doc comment) so `build_matrix_report` parses each file at most once per
/// package.
pub(crate) fn assemble_runtime_versions(
pub(crate) fn add_release_artifact_groups(
    report: &mut MatrixReport,
    artifacts: &[ReleaseArtifactInput],
) -> Result<(), GraphError> {
    const SOURCE: &str = "[[release.artifact]]";
    for artifact in artifacts {
        let group = report
            .platform_targets
            .entry(artifact.id.display_name())
            .or_insert_with(|| PlatformTargetGroup {
                kind: PlatformTargetKind::Cargo,
                source: SOURCE.to_owned(),
                targets: Vec::new(),
            });
        if group.kind != PlatformTargetKind::Cargo {
            return Err(GraphError::PlatformTargetsWithReleaseArtifacts {
                package: artifact.id.clone(),
                source_field: group.source.clone(),
            });
        }
        match build_platform_target(&artifact.target, &artifact.dir_rel, &artifact.name) {
            Some(mut target) => {
                target.artifact_name = artifact.asset_name.clone();
                group.targets.push(target);
            }
            None => report.diagnostics.push(Diagnostic {
                code: DiagnosticCode::UnrecognisedPlatformTriple,
                severity: DiagnosticSeverity::Warning,
                message: format!(
                    "package `{}` declares unrecognised platform triple `{}` in `{SOURCE}`",
                    artifact.name, artifact.target
                ),
                package: Some(artifact.id.clone()),
                path: None,
                escalated_by: None,
                governed_by: None,
            }),
        }
        group.targets.sort_by(|a, b| {
            a.triple
                .cmp(&b.triple)
                .then_with(|| a.artifact_name.cmp(&b.artifact_name))
        });
    }
    report
        .platform_targets
        .retain(|_, group| !group.targets.is_empty() || group.kind != PlatformTargetKind::Cargo);
    Ok(())
}

