1072	pub fn render_workflow(facts: &InitFacts, shape: WorkflowShape, branch: &str, commit: &str, version: &str) -> String {
1073	    let mut secrets = Vec::new();
1074	    if facts.ecosystems.contains(&Ecosystem::Cargo) {
1075	        secrets.push("CARGO_REGISTRY_TOKEN: ${{ secrets.CARGO_REGISTRY_TOKEN }}".to_owned());
1076	    }
1077	    if facts.ecosystems.contains(&Ecosystem::Npm) {
1078	        secrets.push("NPM_TOKEN: ${{ secrets.NPM_TOKEN }}".to_owned());
1079	        // Uses the job's id-token: write; npm publishes no provenance without it.
1080	        secrets.push("NPM_CONFIG_PROVENANCE: \"true\"".to_owned());
1081	    }
1082	    if facts.ecosystems.contains(&Ecosystem::Pypi) {
1083	        secrets.push("PYPI_TOKEN: ${{ secrets.PYPI_TOKEN }}".to_owned());
1084	    }
1085	    secrets.push("GH_TOKEN: ${{ github.token }}".to_owned());
1086	    let env_lines: Vec<String> = secrets.iter().map(|line| format!("          {line}")).collect();
1087	    let release_env = format!("env:\n{}", env_lines.join("\n"));
1088	
1089	    let template = match shape {
1090	        WorkflowShape::Simple => WORKFLOW_TEMPLATE,
1091	        WorkflowShape::BuildMatrix => MATRIX_WORKFLOW_TEMPLATE,
1092	    };
1093	    template
1094	        .replace("__BRANCH__", branch)
1095	        .replace("__COMMIT__", commit)
1096	        .replace("__VERSION__", version)
1097	        .replace("        __RELEASE_ENV__", &format!("        {release_env}"))
1098	}
