193	/// A timed-out `gh attestation verify` is a transient observation, not a hard failure that aborts the release.
194	fn attempt_attestation_verify<R: CommandRunner>(
195	    runner: &R,
196	    args: &[&str],
197	    cwd: &Path,
198	) -> Result<Attempt<bool>, GraphError> {
199	    let observed = match run_observation(runner, programs::GH, args, cwd, timeouts::ATTESTATION_VERIFY, false)? {
200	        Ok(output) => output,
201	        Err(_unavailable) => {
202	            return Ok(Attempt::Transient {
203	                value: false,
204	                retry_after: None,
205	            })
206	        }
207	    };
208	    Ok(Attempt::Settled(observed.success()))
209	}
