 63	///
 64	/// The artifact directory and every candidate are canonicalized, and symbolic
 65	/// links are rejected, so a manifest asset name cannot escape the supplied
 66	/// build-output directory. Each asset is streamed once for a bounded-memory
 67	/// SHA-256 and size comparison. `gh attestation verify` then validates the
 68	/// repository, workflow path and commit, source commit, and hosted-runner
 69	/// policy declared by the immutable artifact slot.
 70	pub fn verify_artifact_manifest<'a, R: CommandRunner>(
 71	    intent: &ReleaseIntentV1,
 72	    manifest: &'a ArtifactManifestV1,
 73	    artifact_root: &Path,
 74	    runner: &R,
 75	) -> Result<VerifiedArtifactManifest<'a>, GraphError> {
 76	    manifest
 77	        .validate_for_intent(intent)
 78	        .map_err(|source| GraphError::ArtifactManifest { source })?;
 79	
 80	    let root = canonical_artifact_root(artifact_root)?;
 81	    for entry in &manifest.entries {
 82	        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
 83	        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
 84	            path: path.clone(),
 85	            message: error.to_string(),
 86	        })?;
 87	        let (digest, length) =
 88	            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
 89	                path: path.clone(),
 90	                message: error.to_string(),
 91	            })?;
 92	        if digest != entry.digest || length != entry.byte_length {
 93	            return Err(GraphError::ArtifactBytesMismatch { path });
 94	        }
 95	
 96	        verify_github_attestation(&path, entry, runner)?;
 97	    }
 98	    Ok(VerifiedArtifactManifest { manifest, root })
 99	}
