101	fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
102	    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
103	        path: artifact_root.to_path_buf(),
104	        message: error.to_string(),
105	    })?;
106	    if !metadata.is_dir() {
107	        return Err(GraphError::UnsafeArtifactPath {
108	            path: artifact_root.to_path_buf(),
109	            reason: "artifact root is not a directory",
110	        });
111	    }
112	    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
113	        path: artifact_root.to_path_buf(),
114	        message: error.to_string(),
115	    })
116	}
117	
118	fn resolve_asset_path(root: &Path, asset_name: &str) -> Result<PathBuf, GraphError> {
119	    let relative = Path::new(asset_name);
120	    if relative.components().count() != 1 || !matches!(relative.components().next(), Some(Component::Normal(_))) {
121	        return Err(GraphError::UnsafeArtifactPath {
122	            path: relative.to_path_buf(),
123	            reason: "asset name is not a single relative file name",
124	        });
125	    }
126	    let candidate = root.join(relative);
127	    let metadata = fs::symlink_metadata(&candidate).map_err(|error| GraphError::ArtifactRead {
128	        path: candidate.clone(),
129	        message: error.to_string(),
130	    })?;
131	    if metadata.file_type().is_symlink() {
132	        return Err(GraphError::UnsafeArtifactPath {
133	            path: candidate,
134	            reason: "symbolic links are not accepted as artifacts",
135	        });
136	    }
137	    if !metadata.is_file() {
138	        return Err(GraphError::UnsafeArtifactPath {
139	            path: candidate,
140	            reason: "artifact is not a regular file",
141	        });
142	    }
143	    let canonical = candidate.canonicalize().map_err(|error| GraphError::ArtifactRead {
144	        path: candidate.clone(),
145	        message: error.to_string(),
146	    })?;
147	    if !canonical.starts_with(root) {
148	        return Err(GraphError::UnsafeArtifactPath {
149	            path: canonical,
150	            reason: "artifact resolves outside artifact root",
151	        });
152	    }
153	    Ok(canonical)
154	}
