156	fn verify_github_attestation<R: CommandRunner>(
157	    path: &Path,
158	    entry: &callisto_model::ArtifactManifestEntryV1,
159	    runner: &R,
160	) -> Result<(), GraphError> {
161	    let attestation_policy = &entry.slot.attestation_policy;
162	    let repository_slug = attestation_policy.repository.as_slug();
163	    let workflow = format!("{repository_slug}/{}", attestation_policy.workflow_path);
164	    let path_argument = path.to_string_lossy();
165	    let source_commit = entry.attestation.source_commit.as_str();
166	    let args = [
167	        "attestation",
168	        "verify",
169	        path_argument.as_ref(),
170	        "--repo",
171	        repository_slug.as_str(),
172	        "--signer-workflow",
173	        workflow.as_str(),
174	        "--signer-digest",
175	        attestation_policy.workflow_commit.as_str(),
176	        "--source-digest",
177	        source_commit,
178	        "--deny-self-hosted-runners",
179	    ];
180	    let cwd = path.parent().unwrap_or_else(|| Path::new("."));
181	    let sleeper = policy::ThreadSleeper;
