   538	    /// Creates the tag `name` at `target_sha`: annotated with `message`
   539	    /// when `Some`, lightweight when `None`. Fails if the tag already
   540	    /// exists. Writes a ref, so it requires an [`ApplyPermit`].
   541	    pub fn create_tag(
   542	        &self,
   543	        name: &str,
   544	        target_sha: &CommitSha,
   545	        message: Option<&str>,
   546	        sign: TagSignPolicy,
   547	        _permit: &ApplyPermit,
   548	    ) -> Result<(), VcsError> {
   549	        let identity = match message {
   550	            Some(_) => self.tagger_identity_override(target_sha)?,
   551	            None => None,
   552	        };
   553	        let mut args: Vec<&str> = Vec::new();
   554	        if let Some([name_config, email_config]) = &identity {
   555	            args.extend(["-c", name_config.as_str(), "-c", email_config.as_str()]);
   556	        }
   557	        // `--` ends option parsing so `name` can never be misread as a flag.
   558	        args.push("tag");
   559	        if let Some(msg) = message {
   560	            args.extend(["-a", "-m", msg]);
   561	        }
   562	        if matches!(sign, TagSignPolicy::ForceUnsigned) {
   563	            args.push("--no-sign");
   564	        }
   565	        args.extend(["--", name, target_sha.as_str()]);
   566	        let output = self.runner.run("git", &args, &self.root)?;
   567	        if !output.success() {
   568	            return Err(VcsError::Git(format!(
   569	                "`git tag` failed in `{}`: {}",
   570	                self.root.display(),
   571	                output.redacted_stderr()
   572	            )));
   573	        }
   574	        Ok(())
   575	    }
   576	
   577	    /// `None` when Git can resolve a committer identity itself. Otherwise the
   578	    /// target commit's committer, as `-c` overrides, since an annotated tag
   579	    /// needs a tagger and a release runner's checkout often configures none.
   580	    fn tagger_identity_override(&self, target_sha: &CommitSha) -> Result<Option<[String; 2]>, VcsError> {
   581	        let ident = self.runner.run("git", &["var", "GIT_COMMITTER_IDENT"], &self.root)?;
   582	        if ident.success() {
   583	            return Ok(None);
   584	        }
   585	        let commit = self
   586	            .runner
   587	            .run("git", &["cat-file", "commit", target_sha.as_str()], &self.root)?;
   588	        let committer = commit
   589	            .stdout
   590	            .lines()
   591	            .take_while(|line| !line.is_empty())
   592	            .find_map(|line| line.strip_prefix("committer "))
   593	            .and_then(|ident| ident.split_once(" <"))
   594	            .and_then(|(name, rest)| Some((name, rest.split_once('>')?.0)));
   595	        match committer {
   596	            Some((name, email)) if commit.success() && !name.is_empty() && !email.is_empty() => {
   597	                Ok(Some([format!("user.name={name}"), format!("user.email={email}")]))
   598	            }
   599	            _ => Err(VcsError::Git(format!(
   600	                "no Git identity for the tagger and could not read the committer of `{}`: {}",
   601	                target_sha.as_str(),
   602	                commit.redacted_stderr()
   603	            ))),
   604	        }
