 70	/// Everything `init` detects before asking a question.
 71	#[derive(Clone, Debug)]
 72	pub struct InitFacts {
 73	    pub root: PathBuf,
 74	    pub ecosystems: BTreeSet<Ecosystem>,
 75	    pub packages: Vec<InitPackage>,
 76	    /// Canonical `origin` push URL, or `None` when no `origin` remote is configured.
 77	    pub origin: Option<String>,
 78	    /// `origin` as a GitHub `owner/repo`, when it is one.
 79	    pub origin_repository: Option<GitHubRepository>,
 80	    /// Non-default tag templates to write, keyed by qualified package id.
 81	    pub tag_templates: BTreeMap<String, String>,
 82	    /// `false` in a repository with no commit yet, where no release can be planned.
 83	    pub has_commit: bool,
 84	    /// A package ships napi/maturin platform builds -- either its own canonical
 85	    /// manifest is platform-tagged, or a platform package is attached to it from
 86	    /// a sibling directory (`IdentityIndex::platforms_of`, e.g. napi's per-arch
 87	    /// packages). Mirrors `commands::release::local::ci_release_route`'s own
 88	    /// platform-package check.
 89	    pub has_platform_packages: bool,
 90	    /// Some package declares `napi.targets` (`callisto matrix`'s napi entries).
 91	    pub has_napi_targets: bool,
 92	    /// Some package declares `[tool.maturin].targets`.
 93	    pub has_maturin_targets: bool,
 94	}
 95	
 96	impl InitFacts {
 97	    pub fn binary_packages(&self) -> impl Iterator<Item = &InitPackage> {
 98	        self.packages.iter().filter(|package| package.is_binary())
 99	    }
100	
101	    /// Resolves `name` (qualified or bare) to a binary-producing package.
102	    pub fn product_package(&self, name: &str) -> Result<&InitPackage, GraphError> {
103	        let invalid = |reason| GraphError::InitInvalidProductPackage {
104	            package: name.to_owned(),
105	            reason,
106	            candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
107	        };
108	        let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
109	            Some(package) => vec![package],
110	            None => self.packages.iter().filter(|package| package.name() == name).collect(),
111	        };
463	pub fn validate_targets(targets: &[String]) -> Result<Vec<String>, GraphError> {
464	    let mut seen = BTreeSet::new();
465	    for target in targets {
466	        let invalid = |reason| GraphError::InitInvalidTargetTriple {
467	            triple: target.clone(),
468	            reason,
469	        };
470	        if target.trim().is_empty() {
471	            return Err(invalid("it is empty"));
472	        }
473	        if !seen.insert(target.as_str()) {
474	            return Err(invalid("it is given more than once"));
475	        }
476	    }
477	    Ok(targets.to_vec())
478	}
