 101	    /// Resolves `name` (qualified or bare) to a binary-producing package.
 102	    pub fn product_package(&self, name: &str) -> Result<&InitPackage, GraphError> {
 103	        let invalid = |reason| GraphError::InitInvalidProductPackage {
 104	            package: name.to_owned(),
 105	            reason,
 106	            candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
 107	        };
 108	        let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
 109	            Some(package) => vec![package],
 110	            None => self.packages.iter().filter(|package| package.name() == name).collect(),
 111	        };
 112	        match found.as_slice() {
 113	            [package] if package.is_binary() => Ok(package),
 114	            [_] => Err(invalid("it does not produce a binary artifact")),
