 158	/// Detects the workspace facts `init` reports and builds on.
 159	///
 160	/// # Errors
 161	///
 162	/// An existing `callisto.toml`, no Git repository, no usable `origin`, or an
 163	/// ambiguous tag convention.
 164	pub fn detect<L: ProjectLocator, R: CommandRunner>(
 165	    root: &Path,
 166	    locator: &L,
 167	    runner: &R,
 168	) -> Result<InitFacts, GraphError> {
 169	    let root = canonical_root(root)?;
 170	    ensure_uninitialized(&root)?;
 171	    let git_dir = runner.run_with_timeout(programs::GIT, &["rev-parse", "--git-dir"], &root, timeouts::LOCAL_GIT)?;
 172	    if git_dir.exit_code != Some(0) {
 173	        return Err(GraphError::InitNotGitRepository { root });
 174	    }
 175	    let origin = optional_git_remote(&root, runner)?;
 176	    let head = runner.run_with_timeout(
 177	        programs::GIT,
 178	        &["rev-parse", "--verify", "--quiet", "HEAD"],
 179	        &root,
 180	        timeouts::LOCAL_GIT,
 181	    )?;
 182	
 183	    let discovered = Workspace::load(root.clone(), locator, runner)?;
 184	    let tag_templates = detect_tag_templates(&discovered)?;
 185	    let templates_only = InitFacts {
 186	        root: root.clone(),
 187	        ecosystems: BTreeSet::new(),
 188	        packages: Vec::new(),
 189	        origin: origin.as_ref().map(|remote| remote.endpoint.clone()),
 190	        origin_repository: origin.as_ref().and_then(|remote| remote.github_repository.clone()),
 191	        tag_templates,
 192	        has_commit: head.exit_code == Some(0),
 193	        has_platform_packages: false,
 194	        has_napi_targets: false,
 195	        has_maturin_targets: false,
 196	    };
 197	    let config = resolve_config_text(
 198	        &root,
 199	        &render_config(
 200	            &templates_only,
 201	            &InitAnswers {
 202	                versioning: Versioning::Independent,
 203	                binaries: None,
 204	            },
 205	        ),
 206	    )?;
 207	    let workspace = Workspace::load_with_config(root.clone(), config, locator, runner)?;
 208	    let tags = workspace.tags()?;
 209	    let versions = workspace.base_versions()?;
 210	    let ctx = callisto_manifests::OpenContext::for_workspace_root(&workspace.root);
 211	
 212	    let mut packages = Vec::new();
 213	    for package in workspace.graph.packages() {
 214	        let mut bin_names = Vec::new();
 215	        for decl in package.canonical_manifests() {
 216	            let manifest = crate::manifest_cache::open_cached(&workspace.manifest_cache, decl, &ctx)?;
 217	            bin_names.extend(manifest.bin_names());
 218	        }
 219	        packages.push(InitPackage {
 220	            id: qualified_id(package),
 221	            version: versions[&package.id].clone(),
 222	            bin_names,
 223	            last_tag: tags.last_tag(&package.id).map(|tag| tag.name.clone()),
 224	            publish_to: package
 225	                .publish_to
 226	                .iter()
 227	                .map(|target| target.config_str().to_owned())
 228	                .filter(|target| target != PublishTarget::None.config_str())
 229	                .collect(),
 230	            platform: is_platform_package(package),
 231	        });
 232	    }
 233	    packages.sort_by(|a, b| a.id.cmp(&b.id));
 234	    let ecosystems = workspace
 235	        .graph
 236	        .packages()
 237	        .flat_map(|package| package.canonical_manifests())
 238	        .map(|manifest| manifest.ecosystem())
 239	        .collect();
 240	    // Counts attached platform packages too: they never get their own `packages` entry,
 241	    // so scanning canonical manifests alone finds only co-located ones.
 242	    let has_platform_packages = workspace
 243	        .graph
 244	        .packages()
 245	        .any(|package| is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some());
 246	
 247	    let matrix = crate::commands::matrix::matrix(&workspace, &crate::commands::matrix::MatrixOptions::default())?;
 248	    let has_kind = |kind| matrix.platform_targets.values().any(|group| group.kind == kind);
 249	
 250	    Ok(InitFacts {
 251	        ecosystems,
 252	        packages,
 253	        has_platform_packages,
 254	        has_napi_targets: has_kind(callisto_model::PlatformTargetKind::Napi),
 255	        has_maturin_targets: has_kind(callisto_model::PlatformTargetKind::Maturin),
 256	        ..templates_only
 257	    })
 258	}
