 415	fn resolve_config_text(root: &Path, text: &str) -> Result<ResolvedConfig, GraphError> {
 416	    let raw = toml::from_str::<RawConfig>(text).map_err(|error| ConfigError::ParseToml {
 417	        path: root.join("callisto.toml"),
 418	        message: error.to_string(),
 419	    })?;
 420	    Ok(crate::config::resolve(root, raw)?)
