 494	/// Writes `callisto.toml` and, when absent, `.changeset/README.md`.
 495	///
 496	/// # Errors
 497	///
 498	/// `callisto.toml` already exists, or a write fails.
 499	pub fn write(root: &Path, config: &str, permit: &ApplyPermit) -> Result<InitReport, GraphError> {
 500	    ensure_uninitialized(root)?;
 501	    let config_path = root.join("callisto.toml");
 502	    let files = init_files(root, false);
 503	    callisto_model::atomic::atomic_write(&config_path, config, permit).map_err(io_err(&config_path))?;
 504	    write_changeset_readme(root, permit)?;
 505	    Ok(InitReport {
 506	        schema_version: SCHEMA_VERSION,
 507	        initialized: true,
 508	        config_path,
 509	        config: config.to_owned(),
 510	        files,
 511	        diagnostics: Vec::new(),
 512	    })
 513	}
