 515	/// Creates `.changeset/README.md` unless it already exists.
 516	///
 517	/// # Errors
 518	///
 519	/// A directory or file write fails.
 520	pub fn write_changeset_readme(root: &Path, permit: &ApplyPermit) -> Result<(), GraphError> {
 521	    let readme = root.join(".changeset/README.md");
 522	    if readme.exists() {
 523	        return Ok(());
 524	    }
 525	    let changeset_dir = root.join(".changeset");
 526	    std::fs::create_dir_all(&changeset_dir).map_err(io_err(&changeset_dir))?;
 527	    callisto_model::atomic::atomic_write(&readme, CHANGESET_README, permit).map_err(io_err(&readme))
 528	}
