1100	/// Errors if a workflow file already exists at [`workflow_path`], without writing.
1101	///
1102	/// # Errors
1103	///
1104	/// A file already exists at that path.
1105	pub fn ensure_workflow_absent(root: &Path) -> Result<(), GraphError> {
1106	    let path = workflow_path(root);
1107	    if path.exists() {
1108	        return Err(GraphError::InitWorkflowExists { path });
1109	    }
1110	    Ok(())
1111	}
