1113	/// Writes the generated release workflow.
1114	///
1115	/// # Errors
1116	///
1117	/// A workflow file already exists at [`workflow_path`], or the write fails.
1118	pub fn write_workflow(root: &Path, content: &str, permit: &ApplyPermit) -> Result<(), GraphError> {
1119	    ensure_workflow_absent(root)?;
1120	    let path = workflow_path(root);
1121	    callisto_model::atomic::atomic_write(&path, content, permit).map_err(io_err(&path))
1122	}
