 619	/// The workflow shape `init` generates for this workspace and answers.
 620	///
 621	/// # Errors
 622	///
 623	/// The workspace has a shape no generated workflow covers.
 624	pub fn workflow_shape(facts: &InitFacts, answers: &InitAnswers) -> Result<WorkflowShape, WorkflowUnsupported> {
 625	    if facts.has_maturin_targets {
 626	        Err(WorkflowUnsupported::Maturin)
 627	    } else if facts.has_platform_packages && !facts.has_napi_targets {
 628	        Err(WorkflowUnsupported::PlatformPackagesWithoutNapiTargets)
 629	    } else if answers.binaries.is_some() || facts.has_platform_packages {
 630	        Ok(WorkflowShape::BuildMatrix)
 631	    } else {
 632	        Ok(WorkflowShape::Simple)
 633	    }
 634	}
