1827	    /// The text of `job`'s block: from its `  <job>:` line to the next job's.
1828	    fn job<'a>(workflow: &'a str, job: &str) -> &'a str {
1829	        let start = workflow
1830	            .find(&format!("\n  {job}:\n"))
1831	            .unwrap_or_else(|| panic!("no job `{job}`"))
1832	            + 1;
1833	        let rest = &workflow[start..];
1834	        let end = rest
1835	            .match_indices("\n  ")
1836	            .find(|(index, _)| !rest[index + 3..].starts_with(' '))
1837	            .map_or(rest.len(), |(index, _)| index);
1838	        &rest[..end]
1839	    }
