2011	    /// Real git, except `ls-remote --symref` answers from `remote_head` instead of touching
2012	    /// the network -- `workspace()`'s `origin` is a real GitHub URL that must never be contacted.
2013	    struct StubRemoteHead {
2014	        remote_head: Option<&'static str>,
2015	    }
2016	    impl CommandRunner for StubRemoteHead {
2017	        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
2018	            RealGitRunner.run(program, args, cwd)
2019	        }
2020	        fn run_quiet(
2021	            &self,
2022	            program: &str,
2023	            args: &[&str],
2024	            cwd: &Path,
2025	            timeout: std::time::Duration,
2026	        ) -> Result<CommandOutput, CommandError> {
2027	            if args.first() == Some(&"ls-remote") {
2028	                return Ok(match self.remote_head {
2029	                    Some(branch) => CommandOutput {
2030	                        exit_code: Some(0),
2031	                        stdout: format!(
2032	                            "ref: refs/heads/{branch}\tHEAD\n0000000000000000000000000000000000000000\tHEAD\n"
2033	                        ),
2034	                        stderr: String::new(),
2035	                    },
2036	                    None => CommandOutput {
2037	                        exit_code: Some(128),
2038	                        stdout: String::new(),
2039	                        stderr: "fatal: could not read Username for 'https://github.com': terminal prompts disabled\n"
2040	                            .to_owned(),
2041	                    },
2042	                });
2043	            }
2044	            RealGitRunner.run_with_timeout(program, args, cwd, timeout)
2045	        }
2046	    }
