   267	/// Matches each package's tags against the candidate conventions; returns the non-default ones to write.
   268	fn detect_tag_templates<R: CommandRunner, D: DependencyResolver>(
   269	    workspace: &Workspace<'_, R, D>,
   270	) -> Result<BTreeMap<String, String>, GraphError> {
   271	    let all_tags = crate::tags::fetch_all_tags(workspace.git_access())?;
   272	    let mut matches: BTreeMap<String, Vec<TagMatch>> = BTreeMap::new();
   273	    for package in workspace
   274	        .graph
   275	        .packages()
   276	        .filter(|package| !is_platform_package(package))
   277	    {
   278	        let grammar = package.version_grammar()?;
   279	        for convention in TAG_CONVENTIONS {
   280	            let rendered = if convention == DEFAULT_TAG_CONVENTION {
   281	                TagTemplate::default_for(&package.id).as_str()
   282	            } else {
   283	                convention.replace("{name}", package.id.name())
   284	            };
   285	            let Ok(template) = TagTemplate::parse(&rendered) else {
   286	                continue;
   287	            };
   288	            // A leading digit keeps `{name}-{version}` from claiming `{name}-v1.0.0` under PEP 440.
   289	            let tags: Vec<String> = all_tags
   290	                .iter()
   291	                .filter(|tag| {
   292	                    template.extract_version_str(tag).is_some_and(|version| {
   293	                        version.starts_with(|c: char| c.is_ascii_digit()) && Version::parse(version, grammar).is_ok()
   294	                    })
   295	                })
   296	                .cloned()
   297	                .collect();
   298	            if !tags.is_empty() {
   299	                matches.entry(qualified_id(package)).or_default().push(TagMatch {
   300	                    convention,
   301	                    template: rendered,
   302	                    tags,
   303	                });
   304	            }
   305	        }
   306	    }
   307	
   308	    let shared: Vec<String> = matches
   309	        .iter()
   310	        .filter(|(_, found)| found.iter().any(|found| found.convention == SHARED_TAG_CONVENTION))
   311	        .map(|(package, _)| package.clone())
   312	        .collect();
   313	    if shared.len() > 1 {
   314	        return Err(GraphError::InitSharedVersionTag { packages: shared });
   315	    }
   316	
   317	    let mut templates = BTreeMap::new();
   318	    for (package, found) in matches {
   319	        match found.as_slice() {
   320	            [only] => {
   321	                if only.convention != DEFAULT_TAG_CONVENTION {
   322	                    templates.insert(package, only.template.clone());
   323	                }
   324	            }
   325	            _ => {
   326	                return Err(GraphError::InitTagTemplateAmbiguous {
   327	                    package,
   328	                    matches: found
   329	                        .iter()
   330	                        .map(|found| format!("`{}` ({})", found.template, found.tags.join(", ")))
   331	                        .collect(),
   332	                })
   333	            }
   334	        }
   335	    }
   336	    Ok(templates)
   337	}
